import type { KBArticle } from '../types';

const day = (d: number) => new Date(Date.now() + d * 86_400_000).toISOString();

export const importedKBArticles: KBArticle[] = [
  { id: "imp-1", title: "Desktop PC won't turn on, and there are no LED lights on the motherboard.", content: "1. Verify the power cable is seated firmly and the switch on the back of the Power Supply Unit (PSU) is set to 'I'.\n2. Test the wall outlet with another device.\n3. If the outlet works, perform a \"paperclip test\" on the 24-pin ATX connector to bypass the motherboard and test if the PSU fan spins.\n4. If it doesn't, replace the PSU.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-2", title: "Laptop has power light but the screen is completely black when turned on.", content: "1. Perform a hard reset by disconnecting the charger, removing the battery (if removable), and holding the power button for 60 seconds.\n2. Reconnect and power on.\n3. If still black, plug in an external monitor via HDMI.\n4. If external video works, the LCD backlight or inverter has failed and requires hardware replacement.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-3", title: "MacBook Pro shows a black screen but plays the startup chime (Intel) or keyboard backlight turns on (M-series).", content: "1. Reset the SMC (Intel) by shutting down, holding Shift+Ctrl+Option+Power for 10 seconds.\n2. For M-series Macs, force a shutdown and press power for 10 seconds to reset the power management.\n3. If the issue persists, boot into Recovery Mode (Intel: Option+Cmd+R | M-series: Hold power until startup options appear) and run Disk Utility First Aid.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-4", title: "Workstation is running extremely slowly, and the hard drive activity light is constantly solid.", content: "1. Open Task Manager (Ctrl+Shift+Esc) and sort by Disk usage.\n2. If at 100%, disable Windows Search (Superfetch) and SysMain services temporarily.\n3. Run CrystalDiskInfo to check the S.M.A.R.T. health of the drive.\n4. If the drive is a failing mechanical HDD, clone the OS to an SSD using Macrium Reflect and replace the drive.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-5", title: "Laptop shuts down randomly after 15-20 minutes of use without warning.", content: "1. This is classic thermal throttling/shutdown.\n2. Boot into BIOS and check hardware monitoring; if CPU/GPU temps are above 90°C, the heatsink needs servicing.\n3. Power off, open the chassis, use compressed air to blow out dust from the fan and heatsink fins, and reapply high-quality thermal paste (e.g., Arctic MX-4) to the CPU/GPU die.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-6", title: "External monitor displays \"No Signal\" despite being plugged into the laptop.", content: "1. Press Windows Key + P and select \"Duplicate\" or \"Extend\".\n2. If that fails, open Device Manager, expand Display Adapters, right-click the GPU, and select \"Update Driver\".\n3. Test the HDMI/DisplayPort cable on another device to rule out a severed pin in the cable.\n4. Ensure the monitor is set to the correct input source via its onboard menu.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-7", title: "iMac screen has a bright line running vertically down the display.", content: "1. A vertical line on an LCD/LED panel indicates a hardware failure in the display matrix or the T-CON board.\n2. Take a screenshot (Cmd+Shift+3).\n3. If the line appears in the screenshot, it's a GPU/logic board issue.\n4. If the line does NOT appear in the screenshot, the LCD panel itself is physically damaged and must be replaced.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-8", title: "Windows PC frequently crashes with a Blue Screen of Death (BSOD) showing \"WHEA_UNCORRECTABLE_ERROR\".", content: "1. This error is almost always hardware-related.\n2. First, update your BIOS and chipset drivers.\n3. Second, run MemTest86 (bootable USB) for at least 4 passes to check for bad RAM.\n4. Third, use HWMonitor to check if the CPU Vcore is fluctuating wildly (indicating PSU or motherboard VRM failure).", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-9", title: "Mac Mini fan runs at maximum speed constantly, sounding like a jet engine.", content: "1. Reset the SMC (unplug for 15 seconds, plug back in, wait 5 seconds, power on).\n2. If the issue persists, open Activity Monitor and sort by %CPU to find a runaway process.\n3. If nothing is using high CPU, the internal temperature sensor may have failed, requiring a logic board diagnostic by Apple.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-10", title: "Desktop PC randomly restarts while playing games or rendering video.", content: "1. Check Windows Event Viewer -> System log for \"Kernel-Power\" Event ID 41.\n2. This confirms an unexpected power loss.\n3. Check your GPU power cables.\n4. Use OCCT to stress-test the GPU and PSU.\n5. If the PSU fails under load, upgrade to a higher wattage, 80+ Gold certified power supply.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-11", title: "Workstation fails to POST (Power-On Self-Test) after installing new RAM.", content: "1. Power off and ground yourself.\n2. Remove the new RAM.\n3. Check the motherboard manual for supported RAM speeds and ensure the new sticks are on the Qualified Vendor List (QVL).\n4. Reinstall the RAM, ensuring it clicks firmly into the DIMM slots.\n5. If it still fails, test the new RAM one stick at a time to isolate a faulty module.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-12", title: "Laptop hinge is physically broken, causing the plastic casing to crack.", content: "1. Advise the user to stop opening/closing the laptop to prevent severing the LCD ribbon cable.\n2. Order a replacement hinge and bottom cover/top lid specific to the laptop's exact model number.\n3. Back up data immediately, disassemble the screen, replace the hinges, and reassemble.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-13", title: "Hard drive is making a loud, rhythmic clicking noise (\"Click of Death\").", content: "1. CRITICAL: Do not run checkdisk or power cycle the drive repeatedly.\n2. This is a mechanical head crash.\n3. If data is needed, immediately power down the PC and send the drive to a professional clean-room data recovery service (like DriveSavers).\n4. If no data is needed, replace the drive.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-14", title: "PC boots straight into BIOS/UEFI, and the hard drive is not listed under boot options.", content: "1. Open the chassis and verify the SATA data cable and power cable are firmly connected to both the drive and the motherboard.\n2. Try a different SATA port on the motherboard.\n3. If the drive still doesn't show up, the drive's controller board has failed, and the drive must be replaced.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-15", title: "Windows 10/11 is stuck in an infinite \"Getting Windows ready, Don't turn off your computer\" loop.", content: "1. Wait at least 2 hours (it may be installing updates).\n2. If still stuck, hard reset the PC 3 times to trigger the Automatic Repair screen.\n3. Go to Troubleshoot -> Advanced Options -> System Restore, and roll back to before the update.\n4. If that fails, use Command Prompt to run: `dism.exe /online /cleanup-image /restorehealth`.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-16", title: "Laptop battery stops charging at 60% or 80% despite being plugged in overnight.", content: "1. This is usually a software limit to prolong battery lifespan, not a defect.\n2. Check Lenovo Vantage, Dell Power Manager, or MyASUS for \"Conservation Mode\" or \"Maximum Lifespan Mode\" and disable it if the user needs 100% charge.\n3. If the setting is off, perform a battery gauge reset via the laptop's BIOS.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-17", title: "USB 3.0 ports on the front of a desktop PC are not recognizing devices.", content: "1. Open the case and ensure the USB 3.0 internal header cable (usually a thick blue-ended 19-pin cable) is firmly pushed into the motherboard.\n2. If it is seated correctly, check Windows Device Manager for \"Unknown USB Device\" errors, which usually indicates a broken pin inside the front panel connector.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-18", title: "The system date and time reset to 2015 every time the PC is unplugged.", content: "1. The CMOS battery (CR2032) on the motherboard is dead.\n2. Power off the PC, open the case, and use a small flathead screwdriver to pop out the silver coin battery.\n3. Replace it with a new CR2032 battery.\n4. Boot into BIOS to set the correct time and date.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-19", title: "User wants to upgrade their laptop from a 1TB HDD to a 1TB SSD. How do we migrate the OS?", content: "1. Connect the new SSD to the laptop via a USB-to-SATA adapter.\n2. Download Macrium Reflect Free or Clonezilla.\n3. Clone the entire HDD partition to the SSD.\n4. Once complete, power down, swap the physical drives (put SSD where HDD was), boot up, and ensure the BIOS is set to UEFI mode if applicable.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-20", title: "Physical liquid spill occurred on a MacBook keyboard.", content: "1. IMMEDIATE ACTION: Unplug power and hold the power button down for 10 seconds to force a shutdown.\n2. Do NOT turn it back on.\n3. Wipe visible liquid.\n4. Leave the laptop open, upside down (tent position) in a dry, warm area for 48-72 hours.\n5. Inform the user that if it was sugary coffee/soda, the logic board will likely corrode and require a full topcase/replacement.", category: "Computer Repair Hardware", tags: ["computer","repair","hardware","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-21", title: "HP LaserJet displays a \"Paper Jam\" error, but there is absolutely no paper inside the machine.", content: "1. A tiny shred of paper is likely stuck over a sensor flag.\n2. Open the rear door, remove the toner cartridge, and shine a flashlight inside.\n3. Look for small plastic flags (sensors) in the paper path; ensure they can move freely and aren't stuck with dust or a torn piece of paper.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-22", title: "Canon IR Series displays \"Error Code E000\" and refuses to print.", content: "1. Error E000 indicates a fuser temperature error (the fuser failed to heat up or overheated).\n2. Turn off the machine, wait 10 seconds, and turn it back on.\n3. If the error persists immediately, the fuser assembly or the thermistor has failed and requires a hardware replacement by a technician.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-23", title: "Epson inkjet printer displays \"Waste Ink Pad is at the End of its Service Life\".", content: "1. The internal sponge pads that absorb wasted ink are full.\n2. Download the Epson Adjustment Program specific to your printer model.\n3. Run the program, select \"Waste Ink Pad Counter\", click \"Check\", then click \"Initialization\" to reset the counter.\n4. Physically cleaning the pads requires full printer disassembly, so a replacement external waste ink bottle is recommended.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-24", title: "Brother laser printer is printing completely blank pages.", content: "1. Ensure the sealing tape was pulled off the new toner cartridge.\n2. If it was, open the front door and look at the drum unit.\n3. There is a small blue or green plastic tab on the side—slide it back and forth 5-6 times to clean the corona wire, then return it to the home position.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-25", title: "Xerox network printer randomly goes \"Offline\" in Windows for all users.", content: "1. The printer's IP address is likely changing due to DHCP.\n2. Print a configuration page from the printer to get its current IP.\n3. Log into the printer's web interface via a browser, go to Network Settings, and set a Static IP outside the router's DHCP pool (e.g., if router hands out .100-.150, set printer to .200).", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-26", title: "Windows 11 gives \"0x0000011b\" error when trying to install a network printer.", content: "1. This is a known Microsoft security update issue (PrintNightmare).\n2. Open Registry Editor (regedit).\n3. Navigate to: `HKEY_LOCAL_MACHINE\\System\\CurrentControlSet\\Control\\Print`.\n4. Right-click Print, select New -> DWORD (32-bit), name it `RpcAuthnLevelPrivacyEnabled`, and set the Value data to `0`.\n5. Restart the Print Spooler service.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-27", title: "Printouts have repeating black vertical lines or streaks down the page.", content: "1. This indicates a defect on the drum unit.\n2. Remove the toner cartridge and inspect the drum (the shiny green/blue roller).\n3. If there is a line of toner stuck to it, do NOT touch it with bare hands (oils ruin it).\n4. Gently wipe it with a soft, lint-free cloth or a cotton swab with a tiny bit of rubbing alcohol.\n5. If the line is scratched into the drum, replace the drum unit.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-28", title: "Printer prints out pages of random symbols, garbage text, or PCL6 errors instead of documents.", content: "1. The wrong printer driver is installed.\n2. Completely remove the printer from Devices and Printers.\n3. Go to the manufacturer's website, download the exact PCL6 or PostScript driver for your model (avoid universal drivers if possible), and reinstall.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-29", title: "Mac computers cannot find the network printer, but Windows PCs can.", content: "1. macOS struggles with some proprietary network protocols.\n2. On the Mac, go to System Settings -> Printers & Scanners -> Add Printer.\n3. Click the \"IP\" icon at the top.\n4. Enter the printer's static IP address, change the Protocol to \"Line Printer Daemon - LPD\", and leave the Queue blank. macOS will auto-detect the correct drivers.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-30", title: "Paper is feeding through the printer crooked/skewed, causing creases.", content: "1. Remove the paper tray.\n2. Fan the paper stack thoroughly to separate the sheets and remove static.\n3. Look inside the tray; ensure the side and rear paper guides are clicked firmly against the edges of the paper stack (there should be no slack, but don't bend the paper).", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-31", title: "Printer display says \"Load Paper into Tray 1\", but Tray 1 is already full.", content: "1. The paper size setting in the tray does not match what the print job is requesting.\n2. Check the physical paper guides in the tray; if they are set to \"Letter\" but the user is printing \"A4\" (or vice\n3. versa), the printer will halt. Adjust the physical guides to match the paper size, and verify the tray's LCD/LED setting matches.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-32", title: "How to safely clear a severe paper jam near the fuser (back of the printer)?", content: "1. WARNING: The fuser operates at nearly 400°F (200°C).\n2. Turn the printer off and wait 15-20 minutes for it to cool.\n3. Open the rear door.\n4. Do not pull paper upward (it will tear).\n5. Gently pull the jammed paper straight down or straight out toward you, following the natural path of the paper feed.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-33", title: "Printer cannot connect to the new WiFi network after changing the office router.", content: "1. On the printer's LCD panel, navigate to Network Settings -> WiFi Setup -> WiFi Setup Wizard.\n2. Select the new network and enter the password.\n3. If the printer has no screen (like a basic HP LaserJet), press and hold the WiFi button and the Cancel (X) button together for 5 seconds to print a WiFi Direct report, then use the HP Smart app to connect it.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-34", title: "Color printer is printing the wrong colors (e.g., people look green instead of normal).", content: "1. The toner cartridges are installed in the wrong slots.\n2. Open the front door and check the color order (usually CMYK: Cyan, Magenta, Yellow, Black from left to right).\n3. Swap the incorrectly placed cartridges to their proper slots and run a calibration/color registration page from the printer's settings menu.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-35", title: "A print job is stuck in the queue and says \"Deleting\" but never goes away, blocking all other prints.", content: "1. Stop the Print Spooler service (services.msc -> Print Spooler -> Stop).\n2. Open File Explorer and navigate to `C:\\Windows\\System32\\spool\\PRINTERS`.\n3. Delete all files inside this folder.\n4. Go back to services.msc and Start the Print Spooler service.\n5. The stuck job is now cleared.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-36", title: "Envelopes or thick paper constantly jam at the entrance of the printer.", content: "1. Standard trays use thin rubber rollers that slip on thick media.\n2. Open the rear bypass door (or multipurpose tray).\n3. Load the envelopes flap-down, edge-first.\n4. Crucially, go into the printer driver properties on the PC before printing, and change the \"Paper Type\" from \"Plain\" to \"Heavy\" or \"Envelope\".\n5. This slows down the print speed, allowing the rollers to grip.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-37", title: "Printer shows \"Toner Low\" but prints are still perfectly fine. How do I bypass this?", content: "1. Many cartridges have a reset gear.\n2. If yours doesn't, look for a small glass or clear plastic window on the side of the toner cartridge.\n3. Cover this window completely with a small piece of black electrical tape.\n4. The printer's laser sensor will no longer see the toner level and will print until the cartridge is physically empty.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-38", title: "\"Scan to Email\" feature on the network printer suddenly stops working.", content: "1. The SMTP credentials have likely expired or the company changed its password policy.\n2. Log into the printer's web interface via IP address.\n3. Go to Network -> Email Settings.\n4. Test the SMTP connection.\n5. Update the sender email address and password.\n6. Ensure Port 587 and TLS/SSL are enabled.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-39", title: "When doing duplex (double-sided) printing, the second side is printed upside down.", content: "1. This is a driver setting issue.\n2. Go to Printer Properties -> Finishing tab (or Device Settings).\n3. Look for \"Duplex Binding\".\n4. Change it from \"Long Edge\" to \"Short Edge\" (or vice versa).\n5. Long Edge is for standard portrait documents (like a book).\n6. Short Edge is for landscape calendars or tablets.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-40", title: "Printer makes a loud, horrible grinding noise when trying to print.", content: "1. STOP PRINTING IMMEDIATELY to prevent further damage.\n2. A grinding noise usually means a gear is stripped, or a foreign object (staple, paperclip, piece of plastic) has fallen into the paper path and is jamming the gears.\n3. Open all doors and inspect the mechanical path.\n4. If no object is found, a gear in the toner cartridge or drive assembly has failed.", category: "Printer Support", tags: ["printer","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-41", title: "Windows Server 2019/2022 crashes and will not boot into the GUI, just shows a spinning circle.", content: "1. Hard reboot the server.\n2. Modern Windows Server (2016 and later) disables the legacy F8 Advanced Boot Options menu by default, so interrupt the boot process 3 times in a row (hold the power button to force a shutdown as soon as the logo appears, then power back on) to trigger the Windows Recovery Environment (WinRE) automatically.\n3. From WinRE, go to Troubleshoot > Advanced Options > Startup Settings > Restart, then select \"Enable Safe Mode\".\n4. If it boots, the issue is a failing driver or Windows Update; uninstall recent updates via Control Panel.\n5. If Safe Mode fails, boot from a Windows Server Installation USB, select \"Repair your computer\", and run System Restore.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-42", title: "Linux Server (Ubuntu/CentOS) halts on boot with a \"Kernel Panic - not syncing\" error.", content: "1. A kernel panic is usually caused by a corrupted file system, failed storage driver, or bad RAM.\n2. Reboot and select an older kernel version from the GRUB menu.\n3. If that works, check `/var/log/syslog` or `dmesg` for hardware errors.\n4. Run `fsck -y /dev/sdX` on the root partition from recovery mode to repair file system errors.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-43", title: "A Hyper-V Virtual Machine is stuck in a \"Saving\" or \"Paused\" state and cannot be started.", content: "1. Hyper-V automatically pauses VMs if the host server runs out of physical storage space.\n2. Check the host's C: drive or the drive hosting the VM `.vhdx` files.\n3. Free up space.\n4. If the VM is still stuck, open PowerShell as Admin and force-kill the VM process: `Stop-VM -Name \"VMName\" -TurnOff -Force`.\n5. Then start it normally.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-44", title: "Dell/HP Server RAID array shows as \"Degraded\" in the BIOS/PERC utility.", content: "1. A physical drive has failed.\n2. Note the drive bay number (e.g., Drive 0:2).\n3. Physically pull the failed drive.\n4. Insert the new, matching drive.\n5. The RAID controller should automatically detect it and begin a \"Rebuild\".\n6. Critical: Do NOT reboot the server during the rebuild process, as this can corrupt the array.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-45", title: "VMware ESXi host becomes disconnected from vCenter Server and cannot be reconnected.", content: "1. Log directly into the ESXi host's web UI via its IP address.\n2. Check the \"Management Network\" settings to ensure the VLAN tag is correct.\n3. If the network is fine, SSH into the ESXi host and restart the management agents by running: `/etc/init.d/hostd restart` and `/etc/init.d/vpxa restart`.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-46", title: "Windows Server C: drive is 99% full, causing services to fail.", content: "1. Do not delete random files.\n2. Run Disk Cleanup and check \"Previous Windows Installations\".\n3. Navigate to `C:\\Windows\\SoftwareDistribution\\Download` and delete its contents (Windows Update cache).\n4. Check IIS logs (`C:\\inetpub\\logs\\LogFiles`) and truncate or move them.\n5. If SQL Server is installed, shrink the tempdb database.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-47", title: "NAS (Synology/QNAP) reports \"Storage Pool Crashed\" or \"System Partition Damaged\".", content: "1. DO NOT REBOOT.\n2. Rebooting a crashed RAID can cause total data loss.\n3. Log into the web UI.\n4. Check `Storage Manager` -> `HD/SSD` to see if multiple drives show errors (indicating a backplane failure) or just one (drive failure).\n5. If multiple drives failed, power down immediately and contact a data recovery specialist.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-48", title: "Windows Server randomly reboots with Event ID 41 (Kernel-Power) but no BSOD.", content: "1. This is an unexpected power loss.\n2. Since it's a server, check the UPS (Uninterruptible Power Supply) logs to see if it switched to battery.\n3. If on battery power, the server may be configured to shut down too quickly.\n4. If connected to a PDU, check iDRAC/iLO hardware logs for power supply redundancy failures.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-49", title: "Server takes 30+ minutes to boot, hanging at \"Applying Group Policy\" or \"Please Wait\".", content: "1. Unplug the network cable.\n2. If the server boots instantly, it's a network/GPO issue.\n3. The server cannot reach a Domain Controller.\n4. Plug the cable back in and run `gpresult /r` in CMD to see which GPOs are applying.\n5. Check DNS settings on the server's NIC to ensure it points strictly to the internal DC IPs.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-50", title: "How do I perform a Bare-Metal Disaster Recovery of a physical Windows Server?", content: "1. Boot the crashed server using a Veeam Recovery Media or Macrium Reflect USB.\n2. Select \"Bare-Metal Restore\".\n3. Connect to your backup repository (via network or external USB drive).\n4. Select the latest full backup.\n5. Map the partitions to the new physical disks.\n6. Run the restore.\n7. Upon reboot, run `ipconfig /flushdns` and rejoin the domain if necessary.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-51", title: "A Linux server loses connection to a SAN LUN after a network blip.", content: "1. The iSCSI or Fibre Channel session dropped and didn't auto-recover.\n2. Run `rescan-scsi-bus.sh` (if installed) or force a rescan via `/sys/class/scsi_host/hostX/scan`.\n3. If the LUN still won't mount, check `dmesg | tail` for \"target reset\" errors.\n4. You may need to restart the `multipathd` service or the iSCSI initiator (`iscsid`).", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-52", title: "Rack server fans run at 100% speed constantly, even though the room is cold.", content: "1. Check the server's hardware management interface (iDRAC, iLO, XCC).\n2. Look for \"Fan Redundancy\" or \"Fan Policy\".\n3. If a single fan fails or is disconnected, the remaining fans will max out to compensate.\n4. Check the front panel LCD for specific fan error codes (e.g., \"Fan 3 absent\").\n5. Replace the faulty fan.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-53", title: "Windows Event Viewer is flooded with \"NTFS delayed write failed\" errors for a shared drive.", content: "1. CRITICAL: This means Windows is trying to write data to the storage, but the storage is disappearing or failing.\n2. Immediately back up what you can.\n3. Check the physical SATA/SAS cables.\n4. If it's an iSCSI SAN, check the network switch for packet drops or CRC errors.\n5. Run `chkdsk /f /r` on the volume immediately.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-54", title: "Active Directory replication fails between two Domain Controllers with error 8646.", content: "1. Error 8646 means the source DC is missing an object that the destination DC expects.\n2. This is often caused by lingering objects from a decommissioned DC.\n3. Run `repadmin /showrepl` to find the failing pair.\n4. Use `repadmin /removelingeringobjects` to clean up the old metadata, then force replication with `repadmin /syncall /A /d /e`.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-55", title: "Users cannot RDP into a Windows Server, getting \"An internal error has occurred\".", content: "1. Open Group Policy Editor (`gpedit.msc`) on the server.\n2. Navigate to Computer Config -> Admin Templates -> Windows Components -> Remote Desktop Services -> Remote Desktop Session Host -> Security.\n3. Ensure \"Require use of specific security layer\" is set to RDP or Negotiate.\n4. Also, ensure the server's local `Remote Desktop Users` group isn't full.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-56", title: "VMware vMotion fails at 14% with the error \"Failed to connect to MKS on host\".", content: "1. vMotion failing at a low percentage is a network constraint.\n2. Ensure the vMotion VMkernel ports on both ESXi hosts are on the exact same subnet/VLAN.\n3. Check that the physical switch ports have the correct MTU size configured (usually 9000 for jumbo frames, or strictly 1500 if jumbo frames are disabled).", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-57", title: "How to safely expand a virtual hard disk (VHD/VHDX) in Hyper-V?", content: "1. Shut down the VM.\n2. In Hyper-V Manager, edit the disk and increase the size (e.g., from 100GB to 200GB).\n3. Boot the VM.\n4. Open Disk Management (`diskmgmt.msc`).\n5. Right-click the unallocated space next to the C: drive and select \"Extend Volume\".\n6. Follow the wizard to add the space.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-58", title: "SQL Server running on a VM experiences severe I/O latency and timeouts.", content: "1. Check the hypervisor for storage queue depths.\n2. Ensure the SQL VM's virtual disks are provisioned as \"Thick Provision Eager Zeroed\" (VMware) or \"Fixed Size\" (Hyper-V) — never thin provisioned for heavy databases.\n3. Inside SQL, ensure TempDB is split into multiple data files equal to the number of CPU cores.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-59", title: "Active Directory database (NTDS.DIT) becomes corrupted and the DC will not boot.", content: "1. Restart the DC and press F8 during boot.\n2. Select \"Directory Services Restore Mode\" (DSRM).\n3. Log in using the local DSRM administrator password (set during DC promotion).\n4. Open CMD and run: `ntdsutil` -> `Semantic database analysis` -> `Go`.\n5. If it finds errors, run `Go Fixup`.\n6. Restart the server normally.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-60", title: "Server backup (Veeam/Backup Exec) fails every night with \"VSS Snapshot Failed\" error.", content: "1. VSS (Volume Shadow Copy Service) relies on sufficient unallocated space on the volume (at least 10% free) and stable disk I/O.\n2. Check if the C: drive is too full.\n3. If it is a VM, ensure there are no other snapshot/checkpoint processes running simultaneously.\n4. Restart the VSS service (`vssvc`) and the Microsoft Software Shadow Copy Provider service.", category: "Server Support", tags: ["server","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-61", title: "Outlook desktop client is stuck in \"Working Offline\" or \"Disconnected\" status.", content: "1. Click the \"Send/Receive\" tab and uncheck \"Work Offline\".\n2. If it remains disconnected, go to File -> Account Settings -> Account Settings.\n3. Highlight the Exchange account and click \"Repair\".\n4. If repair fails, clear the Outlook cache by closing Outlook and deleting the `.ost` file located in ` %LOCALAPPDATA%\\Microsoft\\Outlook`.\n5. Outlook will rebuild it upon reopening.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-62", title: "Microsoft Teams calls drop randomly or users experience severe audio clipping.", content: "1. In Teams, click the three dots (Settings) -> Privacy.\n2. Ensure \"Allow apps to access your microphone\" is on.\n3. Disable \"Noise suppression\" to see if the router/audio driver is causing the clipping.\n4. Check QoS (Quality of Service) on the network switch to ensure DSCP markings for Teams traffic are not being stripped.\n5. Update the LAN/Wi-Fi driver on the client PC.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-63", title: "Office apps (Word/Excel) prompt for \"Activation Failed\" or \"Unlicensed Product\" despite having a valid license.", content: "1. Open an Office app as Administrator (Right-click -> Run as Admin).\n2. Go to File -> Account.\n3. Click \"Sign Out\" and sign back in with the affected user's corporate credentials.\n4. If that fails, open CMD as Admin and run: `cscript \"C:\\Program Files\\Microsoft Office\\Office16\\ OSPP.VBS\" /dstatus` to check the license count, followed by `/act` to force activation.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-64", title: "User cannot log into M365; MFA prompt is not appearing or texts/calls are not coming through.", content: "1. Log into the Azure Portal (portal.azure.com) as an admin.\n2. Go to Azure AD -> Users -> Authentication Methods.\n3. Check if the user's default MFA method is valid.\n4. If the user lost their phone, click \"Require re-register MFA\" to force them to set up a new method on their next login.\n5. Ensure the Microsoft Authenticator app has \"Allow notifications\" enabled on the phone.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-65", title: "User accidentally deleted a critical folder in Outlook and needs it recovered immediately.", content: "1. In Outlook desktop, click the \"Deleted Items\" folder.\n2. Go to the \"Folder\" tab and click \"Recover Deleted Items\".\n3. Search for the folder or emails, select them, and click \"Restore Selected Items\".\n4. Note: Items are only recoverable here for up to 14 days (configurable by admin) before permanent hard deletion.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-66", title: "A Shared Mailbox is not showing up in a user's Outlook despite being assigned in the Admin Center.", content: "1. Microsoft auto-maps shared mailboxes, but this often fails.\n2. Manual fix: Go to File -> Account Settings -> Account Settings -> Change -> More Settings -> Advanced tab.\n3. Under \"Open these additional mailboxes\", click Add and type the email address of the Shared Mailbox.\n4. Click OK, Apply, and restart Outlook.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-67", title: "OneDrive constantly shows \"Processing changes\" or files get stuck with red \"X\" error icons.", content: "1. OneDrive is struggling to sync a file with an unsupported character (like `~`, `#`, `%`, or trailing spaces) or a file path exceeding 260 characters.\n2. Pause syncing, locate the problematic file via the OneDrive error log (click the blue cloud icon -> Help & Settings -> View sync problems), rename the file/folder to remove illegal characters, and resume sync.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-68", title: "SharePoint document library takes minutes to load or throws a \"503 Service Unavailable\" error.", content: "1. Check the SharePoint Admin Center for active maintenance.\n2. If none, the issue is likely heavy metadata or complex column indexing.\n3. As a workaround, create a new View in the library without Folder expansion and with a limit of 30 items.\n4. For a permanent fix, go to Library Settings -> Indexed Columns and index the most frequently filtered columns.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-69", title: "Excel crashes immediately when opening a file hosted on SharePoint or a network drive.", content: "1. This is often caused by a corrupted Add-in.\n2. Open Excel in Safe Mode by holding `Ctrl` while double-clicking the Excel shortcut.\n3. If it opens, go to File -> Options -> Add-ins.\n4. At the bottom, select \"COM Add-ins\" and click \"Go\".\n5. Uncheck all add-ins and click OK.\n6. Restart Excel normally and re-enable add-ins one by one to find the culprit.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-70", title: "Outlook Out of Office (OOF) auto-replies are not sending to external contacts.", content: "1. By default, many organizations disable external OOF replies to prevent data leakage.\n2. As an admin, connect to Exchange Online via PowerShell.\n3. Run: `Set-Mailbox -Identity \"user@domain.com\" -ExternalOofOptions Enabled`.\n4. Inform the user it may take up to 30 minutes for the change to propagate.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-71", title: "Teams \"Translate\" feature or live captions are not working during meetings.", content: "1. Live translation/captions require the tenant admin to enable them.\n2. Go to Teams Admin Center -> Meetings -> Meeting policies -> Global policy.\n3. Under \"Audio & video\", ensure \"Live captions\" is set to \"Enabled but user can override\".\n4. Additionally, the meeting organizer must have an M365 E3/E5 or Business Premium license for this feature.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-72", title: "Outlook Search returns no results for emails that visibly exist in the inbox.", content: "1. The Windows Search Indexer has corrupted the Outlook cache.\n2. Close Outlook.\n3. Open Control Panel -> Indexing Options -> Advanced.\n4. Under \"Troubleshooting\", click \"Rebuild\".\n5. Alternatively, if using a new Outlook profile, ensure \"Download Indexed Items\" is checked in Account Settings -> Change -> More Settings -> Advanced.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-73", title: "Azure AD Connect sync fails with \"stopped-server\" or \"stopped-extension-dll-exception\".", content: "1. Open the Event Viewer on the on-premises sync server and navigate to Application and Services Logs -> ADSync.\n2. Look for specific errors.\n3. Common fixes: The sync service account password expired (reset in AD and update in ADSync config), or the SQL database used by ADSync ran out of space.\n4. Restart the \"Microsoft Azure AD Sync\" service.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-74", title: "Excel Power Query fails to refresh data from a M365 data source (e.g., SharePoint list).", content: "1. The OAuth token used by Power Query to connect to M365 has expired.\n2. In Excel, go to Data -> Get Data -> Data Source Settings.\n3. Select the SharePoint/M365 source and click \"Edit Permissions\".\n4. Clear the cached credentials and re-authenticate with the user's M365 credentials.\n5. Ensure \"Background refresh\" is disabled during troubleshooting.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-75", title: "User is locked out of ALL M365 services and admin cannot reset password via Admin Center.", content: "1. The user account may have \"Block credential\" enabled, or the tenant is experiencing an authentication outage.\n2. Check `https://admin.microsoft.com/#/ServiceHealth`.\n3. If healthy, go to Azure AD -> Users -> Properties -> Edit \"Block sign in\" and set to No. If still locked, use PowerShell: `Connect-AzureAD` then `Set-AzureADUser -ObjectId \"UPN\" -AccountEnabled $true`.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-76", title: "In Teams meetings, the \"Presenter\" cannot share their screen, the button is greyed out.", content: "1. Screen sharing requires specific meeting policies.\n2. Go to Teams Admin Center -> Users -> [Select User] -> Edit Policies.\n3. Ensure the \"Meetings\" policy assigned to them has \"Screen sharing mode\" set to \"Entire Screen\" rather than \"Single application\".\n4. Mac users must also grant Teams \"Screen Recording\" permissions in macOS System Preferences.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-77", title: "Shared Calendars in Outlook are not updating, or the \"Suggested Meetings\" feature doesn't work.", content: "1. Turn off \"Download Shared Folders\" (Exchange caches these poorly).\n2. Go to File -> Account Settings -> Change -> More Settings -> Advanced tab.\n3. Uncheck \"Download Shared Folders\".\n4. To fix scheduling assistant issues, clear the RoamCache: Close Outlook, navigate to `%LOCALAPPDATA %\\Microsoft\\Outlook`, delete all files starting with `RoamCache`, and restart Outlook.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-78", title: "User cannot access a SharePoint site, getting \"Access Denied\" even though they are in the correct M365 Group.", content: "1. This is a permissions propagation delay.\n2. Go to the SharePoint site -> Gear Icon -> Site Permissions -> Advanced Permissions Settings.\n3. Check if the user is explicitly listed.\n4. If they are part of a group that has access, click \"Check Permissions\", type the user's name, and verify the exact permission levels.\n5. If missing, re-add the M365 Group to the site's Visitors/Members group.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-79", title: "Outlook desktop repeatedly prompts for password, even when \"Remember my credentials\" is checked.", content: "1. Open Windows Control Panel -> Credential Manager -> Windows Credentials.\n2. Look for any entries containing `MicrosoftOffice` or `outlook.office365.com`.\n3. Expand them and click \"Remove\".\n4. Open Outlook; it will prompt once for the password.\n5. Check the registry to ensure `LmCompatibilityLevel` is set to 3 under `HKLM\\SYSTEM\\ CurrentControlSet\\Control\\Lsa`.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-80", title: "Transitioning from Volume License to M365, and older Office versions (2013/2016) will not activate.", content: "1. Microsoft has ended support for Office 2013/2016 connecting to M365 backends.\n2. Uninstall the old VL version of Office via Control Panel.\n3. Download and install the Microsoft Office Deployment Tool (ODT).\n4. Create a `configuration.xml` file specifying the current M365 channel (e.g., Current Channel) and deploy the modern version of Office to the machine.", category: "Microsoft 365", tags: ["microsoft","365","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-81", title: "Gmail stops syncing in Outlook or Apple Mail, throwing an \"Authentication Failed\" or \"Password incorrect\" error.", content: "1. Google disabled \"Less Secure Apps\" and basic authentication.\n2. The mail client must use OAuth2.\n3. In Outlook, remove the Gmail account and re-add it by selecting \"Google\" as the account type to trigger the OAuth web login.\n4. If using Apple Mail, go to System Settings -> Internet Accounts, remove Gmail, and re-add it, ensuring you grant permissions for Mail, Contacts, and Calendars.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-82", title: "Google Meet experiences severe echo or feedback loops for all participants.", content: "1. Ask the user experiencing the echo if they have two browser tabs open with Meet, or if they are sitting next to someone else in the same room also in the Meet.\n2. If not, instruct them to click the three dots at the bottom of Meet -> Settings -> Audio.\n3. Uncheck \"Play a ringtone when joining\" and ensure \"Noise cancellation\" is toggled on.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-83", title: "Google Drive shows \"Storage Full\" but the user cannot find any large files in their Drive.", content: "1. Files might be hidden in the Trash or in \"Shared with me\" (which counts against quota if synced).\n2. Check the Trash and click \"Empty trash\".\n3. Additionally, go to Drive -> Settings -> Manage Apps.\n4. Google Drive stores hidden app data (like WhatsApp backups or old app exports) that doesn't show in\n5. standard folders. Delete orphaned app data here.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-84", title: "User claims important emails are \"missing\" from their Gmail inbox.", content: "1. First, check if the user accidentally clicked the \"Archive\" button (removes from inbox but keeps in \"All Mail\").\n2. Have them search in \"All Mail\".\n3. If not there, check Filters (Settings -> See all settings -> Filters and Blocked Addresses) to see if an autodelete or auto-archive rule was created.\n4. Also, check if the email was routed to another folder via routing rules in the Admin Console.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-85", title: "User is locked out of their Google Workspace account and cannot reset their password.", content: "1. Admin intervention required.\n2. Log into Google Workspace Admin Console -> Directory -> Users.\n3. Click the user's name -> Reset Password.\n4. If the user has 2-Step Verification (2SV) and lost their phone, click \"Turn off 2-Step Verification\" temporarily, reset the password, and force them to re-enroll their 2SV methods upon next login.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-86", title: "Google Docs or Sheets frequently disconnects and shows \"Saving failed\" or \"Unable to save.\"", content: "1. This is a local network instability issue blocking Google's WebSocket connections.\n2. Ensure the user is not using a strict proxy or firewall that blocks `*.google.com` or specific ports.\n3. Ask them to disconnect from VPN (if on a consumer VPN) and retry.\n4. If on a corporate network, whitelist Google's IP ranges in the firewall.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-87", title: "When sharing a Google Drive file, external users get \"You need permission\" even though \"Anyone with the link\" is selected.", content: "1. The Google Workspace admin has likely disabled external sharing at the organizational level.\n2. Go to Admin Console -> Apps -> Google Workspace -> Drive and Docs -> Sharing Settings.\n3. Ensure \"Allow sharing outside your organization\" is checked, and that the specific OU (Organizational Unit) the user belongs to is not inheriting a restrictive policy from the root.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-88", title: "Google Workspace Sync for Microsoft Outlook (GWSMO) causes Outlook to freeze or crash frequently.", content: "1. GWSMO creates a massive local `.ost` file that often corrupts.\n2. Close Outlook.\n3. Open the GWSMO utility from the Windows System Tray.\n4. Click \"Google Apps Sync\" -> Set up a Google Apps Sync profile.\n5. Create a new profile.\n6. If issues persist, disable syncing of Google Hangouts chats in GWSMO settings, as chat histories notoriously cause Outlook instability.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-89", title: "Google Meet Grid View or third-party Chrome extensions cause the browser to crash.", content: "1. Google natively added Grid View (Tiled layout), making third-party extensions redundant and often incompatible.\n2. Remove the extension from `chrome://extensions/`.\n3. During a Meet, click the three dots -> \"Change layout\" and select \"Tiled\".\n4. If the browser still crashes, turn off hardware acceleration in Chrome Settings -> System -> \"Use hardware acceleration when available\".", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-90", title: "User tries to attach a 50MB file to Gmail and gets the \"Attachment exceeds limit\" error.", content: "1. Gmail has a strict 25MB limit for *direct* attachments.\n2. When the user drags and drops a file larger than 25MB, Gmail should automatically prompt to \"Insert using Drive\".\n3. If it doesn't, manually upload the file to Google Drive, set the sharing permissions to \"Anyone with the link\", and paste the link into the email body.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-91", title: "Google Calendar \"Find a Time\" feature shows \"No available timeslots\" for a meeting with 2 people.", content: "1. This happens when users have overlapping \"Working Hours\" and \"Working Location\" settings set incorrectly.\n2. Go to Calendar Settings -> General -> Working hours & location.\n3. Ensure the primary time zone is correct and working days are checked.\n4. Also, ensure neither user has an \"All Day\" event marked as \"Busy\" blocking the whole day.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-92", title: "Outbound emails sent through Google Workspace are being rejected by external domains (e.g., \"550 SPF fail\").", content: "1. The domain's DNS is missing or has an incorrect SPF record.\n2. Go to your domain registrar's DNS settings.\n3. Ensure there is a TXT record for `@domain.com` that includes: `v=spf1 include:_spf.google.com ~all`.\n4. Wait up to 48 hours for DNS propagation.\n5. Use `mxtoolbox.com` to verify the SPF record passes.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-93", title: "An employee was offboarded, and we need to retrieve their Google Drive files.", content: "1. Before deleting the user, go to Admin Console -> Directory -> Users -> Click the user -> Transfer user's data.\n2. Enter the email address of the manager or replacement.\n3. Select Drive, Gmail, and Calendar to transfer.\n4. Note: You must do this *before* deleting the user, as deleted users' data is permanently purged after 20 days.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-94", title: "User's Chrome browser keeps switching to a personal profile instead of their Workspace profile.", content: "1. Chrome profiles often get confused.\n2. Click the profile icon in the top right of Chrome.\n3. Check \"Chrome is syncing\" for the Workspace profile.\n4. If the issue persists, force Chrome to open a specific profile via Windows shortcut: Right-click Chrome shortcut -> Properties -> Target.\n5. Add `--profile-directory=\"Profile 2\"` (or the corresponding folder name from `chrome://version/`) to the end of the target path.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-95", title: "Google Chat messages fail to send, showing a red exclamation mark and \"Message not delivered.\"", content: "1. Ensure the user is not trying to message someone outside the organization if external chat is disabled.\n2. If internal, check if the recipient's account is suspended.\n3. Have the user log out of Chat (`chat.google.com`), clear browser cache, and log back in.\n4. If using the standalone Chat app, ensure it is updated to the latest version.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-96", title: "User cannot send emails \"on behalf of\" or \"as\" a shared alias (e.g., info@company.com).", content: "1. In Google Workspace, you don't \"log in\" as an alias.\n2. The alias must be added to the user's account in the Admin Console (Users -> Aliases).\n3. Then, in Gmail Settings -> Accounts -> \"Send mail as\", click \"Add another email address\".\n4. Enter the alias.\n5. Google will send a verification code to the alias email, which can be found in the user's own inbox, to authorize sending.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-97", title: "Google Sheets `IMPORTDATA` or `IMPORTXML` functions return `#N/A` or \"Loading...\" indefinitely.", content: "1. Google Sheets has a 50-second timeout limit for external fetches.\n2. If the target website is slow, it will fail.\n3. Also, the target site may be blocking Google's server IPs (Cloudflare challenges).\n4. As a workaround, use Google Apps Script (`UrlFetchApp`) to fetch the data, or run the import on a scheduled trigger every hour rather than on every edit.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-98", title: "New employee does not show up in the global directory or cannot access Google Groups.", content: "1. Directory syncing takes time, but check the Admin Console.\n2. Go to Directory -> Groups.\n3. Find the group the user should be in.\n4. Check the \"Who can join\" and \"Who can post\" settings.\n5. If the user is in a specific OU (Organizational Unit), ensure Group policies aren't restricting access based on OU.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-99", title: "Google Forms submissions are not being recorded in Google Sheets.", content: "1. Open the Form -> Responses tab.\n2. Click the Sheets icon.\n3. If it says \"Select existing spreadsheet\", the link is broken.\n4. Unlink the current sheet.\n5. Create a *new* blank Google Sheet, and link the Form to this new sheet.\n6. If it still fails, check if the user has hit the 5 million cell limit in the original spreadsheet.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-100", title: "Admin wants to prevent users from downloading Google Drive files to personal/unmanaged devices.", content: "1. This requires Context-Aware Access or DLP rules (requires Enterprise license).\n2. Go to Admin Console -> Security -> Access and data control -> Context-Aware Access.\n3. Create a level that restricts Drive downloads based on IP address (e.g., only allow downloads if originating\n4. from the company's public IP). Apply this level to the Drive & Docs app.", category: "Google Workspace (Google Suite)", tags: ["google","workspace","suite","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-101", title: "QuickBooks Desktop freezes or hangs when opening a company file over the network.", content: "1. QuickBooks is highly sensitive to network latency.\n2. Open the QuickBooks Database Server Manager on the server hosting the file.\n3. Run a scan and ensure the company file is properly monitored.\n4. On the client PC, open the folder `C:\\Program Files\\Intuit\\QuickBooks [Year]`, find the `QBW32.exe` file, right-click -> Properties -> Compatibility.\n5. Check \"Run this program in compatibility mode for Windows 8\".", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-102", title: "Salesforce (or similar CRM) is loading extremely slowly and timing out in Chrome.", content: "1. CRM interfaces rely heavily on local browser caching and JavaScript.\n2. In Chrome, open Developer Tools (F12) -> Network tab.\n3. Check for failed requests (red text).\n4. Go to `chrome://settings/privacy` -> Clear browsing data (Cached images and files).\n5. Disable hardware acceleration in Chrome settings.\n6. If using a VPN, disconnect it, as VPNs often route CRM traffic inefficiently.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-103", title: "AutoCAD throws a \"Fatal Error\" or \"Unhandled Access Violation\" when saving or panning.", content: "1. Update the GPU driver to the latest \"Studio\" or \"Enterprise\" version (do NOT use Game Ready drivers).\n2. In AutoCAD, type `GRAPHICSCONFIG`, change Hardware Acceleration to \"Off\", and try to save.\n3. If it saves, the issue is definitely GPU-related.\n4. Repair the AutoCAD installation via Windows Control Panel -> Programs and Features.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-104", title: "Adobe Creative Cloud apps (Photoshop/Illustrator) keep asking the user to sign in every time they launch.", content: "1. The Adobe Genuine Service or licensing service is corrupted.\n2. Open Services (`services.msc`), stop \"Adobe Genuine Software Integrity Service\" and set it to Disabled.\n3. Repair the Adobe Creative Cloud app via Windows Settings -> Apps -> Advanced Options -> Repair.\n4. If on a corporate license, ensure the `AdobeGCTL.exe` process isn't being blocked by the corporate firewall.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-105", title: "EDR/Antivirus (CrowdStrike/SentinelOne) flags a legitimate, custom-built internal application as malware and quarantines it.", content: "1. Do not instruct the user to disable AV.\n2. As an admin, log into the EDR management console.\n3. Locate the quarantine alert.\n4. If verified as a false positive, create an \"Exclusion\" or \"Whitelist\" policy.\n5. Exclude the specific file hash (SHA256), the folder path (e.g., `C:\\CustomApp\\*`), and the process name.\n6. Push the policy to the endpoint and restore the file from quarantine.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-106", title: "A legacy custom application fails to install on Windows 11, showing \"This app can't run on your PC\".", content: "1. The app is likely a 16-bit installer or requires an older .NET framework.\n2. Right-click the installer `.exe` -> Properties -> Compatibility.\n3. Check \"Run this program in compatibility mode for Windows 7\" and check \"Run this program as an administrator\".\n4. If it still fails, you may need to enable \"NTVDM\" (NT Virtual DOS Machine) in Windows Features, though Microsoft has deprecated this in Win 11 24H2.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-107", title: "SAP GUI or Oracle ERP client fails to launch, throwing a \"Java Runtime Environment not found\" error.", content: "1. The application requires a specific, older version of Java (e.g., Java 8 Update 301) and will not work with newer versions.\n2. Uninstall all current Java versions.\n3. Download the exact JRE specified by the ERP vendor.\n4. Install it.\n5. Ensure the system environment variable `JAVA_HOME` points to the new JRE folder (e.g., `C:\\Program Files\\Java\\jre1.8.0_301`).", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-108", title: "Adobe Acrobat DC is stuck on \"Updating...\" or rolls back with \"Error 1603\" during updates.", content: "1. Error 1603 is a fatal Windows installer error.\n2. Download the Adobe Creative Cloud Cleaner Tool.\n3. Run it and select \"Acrobat\" to completely wipe all leftover registry keys and files.\n4. Reboot the PC.\n5. Reinstall Adobe Acrobat using the offline installer package provided by the IT admin, not the web-based installer.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-109", title: "After a major version update, accounting software (e.g., Sage 50) gives a \"Database Connection Failed\" error.", content: "1. The update likely changed the database engine (e.g., from Pervasive SQL to Actian Zen).\n2. Go to Windows Services (`services.msc`) and ensure the new database service is running.\n3. If it is, check Windows Firewall.\n4. The new version may use a different executable name (e.g., `w3dbsmgr.exe` vs `ntsqlmgr.exe`) and the old firewall rules are blocking it.\n5. Create a new inbound/outbound rule.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-110", title: "Custom internal app throws \"The program can't start because VCRUNTIME140_1.dll is missing from your computer.\"", content: "1. The app requires the Microsoft Visual C++ Redistributable.\n2. Go to Microsoft's website and download the latest \"Microsoft Visual C++ Redistributable for Visual Studio 2022\".\n3. Ensure you download BOTH the `x86` and `x64` versions and install them both.\n4. Do not uninstall older versions, as other apps may rely on them.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-111", title: "Sage 50 (Peachtree) prints reports with misaligned columns or cuts off text on the right side.", content: "1. Sage 50 relies heavily on default Windows printer drivers.\n2. Go to Windows Settings -> Devices -> Printers & Scanners.\n3. Uncheck \"Let Windows manage my default printer\".\n4. Manually set a standard printer (like Microsoft Print to PDF or a local LaserJet) as the default.\n5. Open Sage and try printing again; the font mapping should correct itself.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-112", title: "A custom application fails to connect to its local SQL Express database with \"Login failed for user 'NT AUTHORITY\\ANONYMOUS LOGON'\".", content: "1. The app is trying to connect using Windows Authentication but losing its credentials.\n2. Open SQL Server Configuration Manager.\n3. Expand SQL Server Network Configuration -> Protocols for SQLEXPRESS.\n4. Ensure \"Named Pipes\" and \"TCP/IP\" are Enabled.\n5. Restart the SQL Server (SQLEXPRESS) service.\n6. Verify the app's config file (`.config` or `.ini`) has `Integrated Security=SSPI;`.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-113", title: "EDR/Antivirus causes the PC to boot incredibly slowly and uses 90% CPU at startup.", content: "1. The EDR is performing a full disk scan at boot.\n2. Open the EDR console.\n3. Schedule the full disk scan to occur during off-hours (e.g., 2:00 AM on Saturdays) rather than at startup.\n4. Add high-I/O folders (e.g., Virtual Machine folders, SQL database folders, `C:\\Windows\\Temp`) to the EDR's exclusion list for on-access scanning.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-114", title: "AutoCAD toolbars, ribbon, or command line disappear, and the crosshair cursor acts erratically.", content: "1. The AutoCAD profile (UI settings) is corrupted.\n2. Type `CUI` in the command line.\n3. If that doesn't work, reset AutoCAD to defaults.\n4. Type `OP` (Options) -> Profiles tab -> Reset.\n5. If completely unresponsive, open Windows File Explorer and navigate to `%APPDATA%\\Autodesk\\ AutoCAD [Version]`.\n6. Rename the `Support` folder to `Support_Old`.\n7. Restart AutoCAD to force it to rebuild a fresh UI profile.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-115", title: "User complains that buttons and menus are missing in a CRM/ERP web interface.", content: "1. This is 99% a Role-Based Access Control (RBAC) issue.\n2. The user's permissions were likely changed.\n3. Do not troubleshoot the browser.\n4. Log into the CRM Admin panel, navigate to User Roles/Profiles, and review the user's assigned role.\n5. Ensure they have the necessary \"Object Permissions\" or \"Page Access\" levels to view those specific UI elements.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-116", title: "A recent Windows Update broke a critical custom application; it now crashes on launch.", content: "1. Roll back the update immediately.\n2. Go to Settings -> Windows Update -> Update History -> Uninstall updates.\n3. Sort by \"Installed On\" and uninstall the most recent `.NET` or OS security update.\n4. To prevent it from happening again, go to Windows Update -> Advanced Options -> Pause Updates.\n5. Report the issue to the app developer.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-117", title: "Adobe Premiere Pro shows \"Low System Memory\" and crashes during video rendering, despite having 32GB of RAM.", content: "1. Premiere relies heavily on GPU VRAM, not just system RAM.\n2. Go to File -> Project Settings -> General.\n3. Change the \"Renderer\" to \"Mercury Playback Engine GPU Acceleration (CUDA/Metal/OpenCL)\".\n4. If it still crashes, go to Edit -> Preferences -> Media Cache -> delete the media cache files.\n5. Ensure the SSD where the cache is located has at least 50GB free space.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-118", title: "Custom app fails to save configuration files, throwing an \"Access Denied\" or \"Path not found\" error.", content: "1. The legacy app is trying to write to `C:\\Program Files\\` or `C:\\Windows\\`, which is blocked by Windows UAC (User Account Control).\n2. Right-click the app's shortcut and select \"Run as Administrator\".\n3. For a permanent fix, change the compatibility settings to \"Run this program as an administrator\", or redirect the app's save path to `%LOCALAPPDATA%` via its `.ini` file.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-119", title: "AutoCAD or Adobe products fail to check out a network license, showing \"License error -96\" or \"-5\".", content: "1. Error -96/-5 means the client cannot reach the FlexNet License Manager service on the server.\n2. Verify the server is online.\n3. Open `services.msc` on the server and ensure \"FlexNet Licensing Service\" is running.\n4. On the client, open a CMD prompt and run `telnet [License_Server_IP] 2080` (Autodesk) or `27000` (Adobe).\n5. If it fails, a firewall is blocking the port.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-120", title: "Cloud-based CRM (e.g., HubSpot/Dynamics) loses unsaved data when the user navigates away or the page refreshes.", content: "1. This is often caused by aggressive browser caching or an unstable connection.\n2. Instruct the user to use a hardwired ethernet connection instead of Wi-Fi.\n3. In the CRM settings, check if there is an \"Auto-save\" draft feature and enable it.\n4. If using Chrome, ensure the site is not set to \"Always clear cookies when windows are closed\" in Privacy settings.", category: "Software Support", tags: ["software","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-121", title: "WordPress site displays a blank white screen (White Screen of Death) with no error messages.", content: "1. A WSOD is a fatal PHP error with debugging disabled.\n2. Connect via FTP/SFTP or cPanel File Manager.\n3. Edit the `wp-config.php` file and add `define( 'WP_DEBUG', true );` and `define( 'WP_DEBUG_LOG', true );` just above \"That's all, stop editing!\".\n4. Refresh the site; the error will now display.\n5. If it points to a plugin, rename the `/wp-content/plugins/` folder via FTP to disable all plugins, then rename it back and reactivate one by one.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-122", title: "Website shows \"Not Secure\" in the browser, or padlock has a strike-through it (Mixed Content Error).", content: "1. The SSL certificate is valid, but the HTML code is loading images, scripts, or CSS over `http://` instead of `https://`.\n2. In WordPress, install the \"Better Search Replace\" plugin, search for `http://yourdomain.com`, replace with `https://yourdomain.com`, select all tables, and run.\n3. For custom sites, check the `.htaccess` file to ensure `HTTPS` enforcement is on, or use browser DevTools (F12 -> Console) to find the exact insecure file paths.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-123", title: "cPanel shows \"Error Establishing a Database Connection\" on a WordPress site.", content: "1. The database credentials in `wp-config.php` are wrong, or the MySQL server is down.\n2. First, check cPanel -> MySQL Databases to ensure the database and user exist.\n3. Next, check cPanel -> Databases -> \"Repair Database\".\n4. If the DB is fine, open `wp-config.php` and verify `DB_NAME`, `DB_USER`, and `DB_PASSWORD` exactly match the cPanel credentials.\n5. Reset the DB user password in cPanel if needed.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-124", title: "Shopify store returns a \"502 Bad Gateway\" or \"500 Internal Server Error\" to visitors.", content: "1. 500/502 errors on Shopify are almost always caused by faulty custom Liquid code or a broken third-party app.\n2. Log into Shopify Admin -> Online Store -> Themes -> Actions -> Edit Code.\n3. Check `theme.liquid` or recently modified snippets for syntax errors (missing `%` or `{{ }}`).\n4. If you recently installed an app, disable it in the Apps section to see if the store recovers.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-125", title: "Wix or Squarespace site is completely unreachable; DNS_PROBE_FINISHED_NXDOMAIN.", content: "1. The domain's DNS is not pointing to the platform.\n2. Log into your domain registrar (GoDaddy, Namecheap, etc.).\n3. If using Wix, point the A record to `76.223.89.66` and the CNAME for 'www' to `www.wixdns.net`.\n4. If using Squarespace, update the nameservers to Squarespace's assigned nameservers (e.g., `ns1.squarespacedns.com`).\n5. DNS propagation takes 1-48 hours.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-126", title: "Custom PHP/Laravel web application throws \"500 Internal Server Error\" on a specific page.", content: "1. Check the server's error logs (cPanel -> Errors, or `/var/log/apache2/error.log` in Linux).\n2. Common causes: hitting the PHP memory limit or execution time limit.\n3. If it's a memory limit, edit the `.htaccess` file in the public root and add `php_value memory_limit 512M`.\n4. If it's a Laravel app, ensure the `storage/` and `bootstrap/cache/` directories have `755` permissions and are owned by the `www-data` user.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-127", title: "Website loads extremely slowly; Google PageSpeed score is in the red.", content: "1. Install a caching plugin (e.g., WP Rocket or LiteSpeed Cache).\n2. Enable page caching, CSS/JS minification, and lazy loading of images.\n3. Run the images through a compressor like TinyPNG.\n4. If using WordPress, disable unnecessary heavy plugins (like statistics or page builders) and ensure the server is using PHP 8.1+ and the latest MySQL version for optimal query performance.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-128", title: "Google Search Console flags the website with \"Detected - hacked\" or users report browser malware warnings.", content: "1. The site has malicious injected scripts.\n2. Isolate the site by putting it in Maintenance Mode.\n3. Scan the server files using ClamAV or Sucuri Scanner.\n4. Look for base64 encoded strings in `index.php` or `wp-config.php`.\n5. Change ALL passwords (cPanel, FTP, WP Admin, DB).\n6. Update all themes/plugins.\n7. Request a malware review in Google Search Console once clean.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-129", title: "Custom web app gives \"403 Forbidden - You don't have permission to access this resource.\"", content: "1. This is a file permission issue on the Linux server.\n2. Connect via SSH.\n3. Navigate to the web root directory (e.g., `/var/www/html`).\n4. Run `sudo chown -R www-data:www-data .` to fix ownership.\n5. Then run `sudo chmod -R 755 .` for directories and `644` for files.\n6. If it's an `.htaccess` issue, ensure `AllowOverride All` is set in the Apache virtual host configuration.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-130", title: "WordPress admin dashboard redirects endlessly back to the login page when trying to log in.", content: "1. This is usually an incorrect `siteurl` or `home` value in the database.\n2. Connect to phpMyAdmin.\n3. Open the `wp_options` table.\n4. Find rows `option_name` for `siteurl` and `home`.\n5. Ensure they exactly match your domain, including `https://` (e.g., `https://www.yourdomain.com`).\n6. If they are wrong, edit them, clear your browser cookies, and try logging in again.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-131", title: "cPanel Cron Jobs are not executing automated tasks (backups, WP cron, etc.).", content: "1. In cPanel -> Cron Jobs, ensure the command is using the absolute path to PHP.\n2. Do not use just `php script.php`.\n3. Use: `/usr/local/bin/php -f /home/username/public_html/script.php`.\n4. Also, ensure you set an active email address in the Cron Jobs page so you receive the output/errors.\n5. Check the server's timezone to ensure the cron schedule aligns with your local time.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-132", title: "Emails sent from the website's contact form never arrive in the recipient's inbox.", content: "1. Shared hosting servers often block native `mail()` functions to prevent spam.\n2. Use an SMTP plugin (like WP Mail SMTP).\n3. Configure it to send emails through a dedicated relay service (SendGrid, Mailgun, or Google Workspace SMTP).\n4. This authenticates the email via API keys or OAuth, bypassing the server's restrictive local mail rules and improving deliverability.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-133", title: "Plesk server shows \"Client denied by server configuration\" when accessing a subdomain.", content: "1. Apache is blocking access via an `.htaccess` rule or directory permissions.\n2. Check the Plesk domain -> Apache & nginx Settings.\n3. Look in the \"Additional directives for HTTP/HTTPS\".\n4. If there is a `Deny from all` rule, remove it.\n5. Alternatively, check if the subdomain's document root has an `.htaccess` file inherited from the main domain causing a conflict.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-134", title: "After migrating a website to a new hosting provider, the homepage works but all inner pages return 404.", content: "1. The web server's rewrite engine is not active, or the `.htaccess` file didn't transfer.\n2. For Apache, ensure `mod_rewrite` is enabled.\n3. For WordPress, go to Settings -> Permalinks and simply click \"Save Changes\" without changing anything; this flushes and rewrites the `.htaccess` rules.\n4. If on Nginx, ensure the permalink rewrite rules are added to the server block configuration.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-135", title: "Website goes down daily at exactly the same time (e.g., 3:00 AM).", content: "1. A scheduled server task is conflicting with the site.\n2. Check cPanel -> Cron Jobs for heavy backups running at that time.\n3. Check if the hosting provider has automated daily backups or log rotations that consume 100% I/O.\n4. Contact the host to stagger backup times, or move your site's backup cron to an off-peak hour.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-136", title: "Shopify store loads fine on desktop but is completely broken/unresponsive on mobile.", content: "1. A recent theme edit likely broke mobile-specific CSS or JavaScript.\n2. Open the theme editor and look for custom CSS wrapped in `@media (max-width: 768px)`.\n3. Revert recent changes.\n4. Also, ensure you haven't disabled \"Ajax Cart\" or \"Dynamic Checkout\" which heavily rely on mobile JS frameworks.\n5. Test using Chrome DevTools mobile emulator to pinpoint the exact element.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-137", title: "SSL certificate renewal fails automatically via Let's Encrypt in cPanel.", content: "1. Let's Encrypt requires port 80 (HTTP) to be open and unblocked to validate the domain.\n2. Ensure no `.htaccess` rule is redirecting `http://` to `https://` *before* the validation happens.\n3. Temporarily disable any HTTP-to-HTTPS redirects in cPanel -> Domains -> Domain Settings.\n4. Run the AutoSSL check again.\n5. Re-enable the redirect after the certificate issues.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-138", title: "A subdirectory (e.g., `domain.com/blog`) works locally but returns a 404 on the live server.", content: "1. The main site's `.htaccess` is overriding the subdirectory.\n2. In the root `.htaccess`, add the following line above the main rewrite rules: `RewriteCond %\n3. {REQUEST_URI} !^/blog/`. This tells Apache to ignore requests for the `/blog/` folder and let the subdirectory's own `.htaccess` (or lack thereof) handle the request.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-139", title: "Custom application throws \"Fatal error: Allowed memory size of 134217728 bytes exhausted\".", content: "1. The PHP script is trying to allocate more RAM than the server allows (128MB in this case).\n2. If you have access to `php.ini`, increase `memory_limit = 512M`.\n3. If on shared hosting without `php.ini` access, create or edit the `.htaccess` file in the root directory and add: `php_value memory_limit 512M`.\n4. If the host blocks this, you must contact them to raise the limit.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-140", title: "Website functions, but images and CSS fail to load, showing a \"ERR_TOO_MANY_REDIRECTS\" error.", content: "1. There is a redirect loop between the web server (Apache/Nginx) and the application code.\n2. Check the `.htaccess` file.\n3. If you have an HTTPS redirect rule AND a Cloudflare \"Flexible SSL\" setting active, they will fight each other.\n4. Fix: Log into Cloudflare -> SSL/TLS -> set to \"Full\" or \"Full (Strict)\", and keep the `.htaccess` HTTPS redirect.", category: "Website Support", tags: ["website","support","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-141", title: "PC shows \"Connected, No Internet\" but can ping internal IP addresses (like the printer).", content: "1. This is a DNS failure.\n2. The PC can reach the local LAN but cannot resolve web addresses.\n3. Open the network adapter settings.\n4. Change the DNS servers from the router's IP to public DNS (e.g., `8.8.8.8` and `1.1.1.1`).\n5. If it works, the issue is your router's DNS forwarder.\n6. Flush the local DNS cache via CMD: `ipconfig /flushdns`.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-142", title: "Office WiFi drops frequently for roaming users moving between rooms.", content: "1. The Access Points (APs) are likely on the same channel, causing interference, or lack proper roaming support.\n2. Use a WiFi analyzer app to check channels.\n3. Set AP1 to Channel 1, AP2 to Channel 6, and AP3 to Channel 11.\n4. If using Ubiquiti, ensure \"Fast Roaming\" is enabled.\n5. If using cheap Netgear/D-Link APs, they don't support 802.11k/v/r seamless roaming; users will drop during handoffs.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-143", title: "Windows PC gets a 169.254.x.x IP address and cannot access the internet or network.", content: "1. The PC is using an APIPA address because the DHCP server is unreachable or full.\n2. First, run `ipconfig /release` then `ipconfig /renew` in CMD.\n3. If it fails, check the Ethernet cable.\n4. If on WiFi, reboot the router.\n5. If it still fails, check the router's DHCP pool to ensure it hasn't run out of available IPs (common in busy offices with a small subnet like /24).", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-144", title: "User cannot access a shared network drive (`\\\\server\\data`), getting \"Network path not found.\"", content: "1. Ensure the PC and Server are on the same subnet or have proper VLAN routing.\n2. If subnet is correct, the issue is usually SMBv1 being disabled on Windows 10/11.\n3. Open \"Turn Windows features on or off\", uncheck \"SMB 1.0/CIFS File Sharing Support\", and reboot.\n4. The server must support SMBv2/v3 (which all modern Windows Server versions do).", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-145", title: "Ubiquiti UniFi Access Point shows \"Offline\" or \"Adopting\" in the UniFi Controller.", content: "1. The AP cannot reach the controller due to an L3 routing issue or firewall block.\n2. If the AP and Controller are on different subnets, you must set up a UniFi L3 Adoption.\n3. SSH into the AP (find its IP via your router's client list) and run: `set-inform http://[CONTROLLER_IP]:8080/inform`.\n4. Ensure port 8080 is open between the subnets.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-146", title: "MikroTik router is completely unresponsive; I've forgotten the admin password and IP.", content: "1. Perform a hardware reset.\n2. Unplug the power.\n3. Press and hold the `RES` button on the back of the MikroTik.\n4. While holding it, plug the power back in.\n5. Hold the button for ~5 seconds until the `ACT` light starts flashing.\n6. Release the button.\n7. The router will reset to `192.168.88.1` with username `admin` and no password.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-147", title: "File transfers over the Gigabit LAN are extremely slow (e.g., 10MB/s instead of 100MB/s).", content: "1. This is a duplex mismatch or bad cabling.\n2. Open CMD and run `ipconfig /all`.\n3. Check the \"Media State\" or look at the switch port LEDs.\n4. If the LED is amber instead of green, it is negotiating at 100Mbps.\n5. Check the cable ends (Cat5e vs Cat6) and re-crimp if necessary.\n6. On the switch, ensure the port is hardcoded to `1000 Mbps Full Duplex` if Auto-Negotiation fails.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-148", title: "A Cisco switch port goes into \"err-disable\" state, turning orange, and drops the connected device.", content: "1. The switch has detected a security violation (like BPDU Guard or Port Security).\n2. SSH into the switch.\n3. Run `show interfaces status err-disabled` to see the reason.\n4. To recover immediately, go to interface config mode and run `shutdown`, then `no shutdown`.\n5. To prevent it, ensure the connected device isn't bridging networks (BPDU) or limit the MAC addresses in port-security.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-149", title: "Device connects to WiFi successfully, but the browser says \"DNS_PROBE_FINISHED_NO_INTERNET\".", content: "1. The device is connected to a captive portal (like a hotel or guest WiFi) but hasn't authenticated.\n2. Open a non-HTTPS site (e.g., `http://neverssl.com`) to force the captive portal login page to appear.\n3. If on a corporate network, \"Forget\" the WiFi network on the device, reconnect, and ensure it doesn't have a static IP configured that bypasses the local DNS.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-150", title: "Devices on VLAN 10 (Sales) cannot communicate with VLAN 20 (HR), but both have internet.", content: "1. Inter-VLAN routing is not configured.\n2. You must have a Layer 3 Switch or a Router configured with \"Router on a Stick\".\n3. On a Cisco L3 switch, enable IP routing (`ip routing` global command).\n4. Create Switch Virtual Interfaces (SVIs) for each VLAN (e.g., `interface vlan 10`, `ip address 192.168.10.1 255.255.255.0`).\n5. Ensure devices use their respective SVI as their default gateway.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-151", title: "A Netgear router is not assigning IP addresses to new devices, but existing devices work fine.", content: "1. The DHCP IP pool is exhausted.\n2. Log into the Netgear router at `192.168.1.1`.\n3. Go to Advanced -> Setup -> LAN Setup.\n4. Check the \"Starting IP Address\" and \"Ending IP Address\".\n5. If it's a /24 network (254 addresses) and you have 250+ devices, you must either reduce the DHCP lease time or upgrade to a larger subnet (e.g., `/23` or 510 addresses).", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-152", title: "A user's laptop \"sticks\" to a distant WiFi AP instead of the closest one, causing weak signal.", content: "1. This is a \"sticky client\" issue.\n2. Windows is notoriously bad at roaming because it only roams when the signal drops below a very low threshold.\n3. Workaround: In Windows Settings -> Network & WiFi -> Manage Known Networks, forget the network.\n4. Reconnect.\n5. If using enterprise APs (Cisco/Ubiquiti), enable \"Minimum RSSI\" (e.g., -70dBm) to forcefully kick devices with weak signals off the AP.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-153", title: "A legitimate employee's laptop is blocked from the network; the switch/AP shows \"MAC Filtered\".", content: "1. Someone enabled MAC filtering on the router/switch.\n2. Log into the management interface.\n3. Navigate to Wireless Settings -> MAC Filtering (or Port Security on a switch).\n4. Either disable MAC filtering entirely (as it provides zero actual security and is easily spoofed), or add the employee's wireless NIC MAC address to the \"Allow\" list.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-154", title: "You can ping external IP addresses (like 8.8.8.8) but cannot browse websites by name.", content: "1. Confirmed DNS failure.\n2. Open CMD and type `nslookup google.com`.\n3. If it returns \"Server Failed\", check your network adapter's IPv4 properties.\n4. Ensure the DNS server is pointing to a valid server (e.g., your internal DC or `8.8.8.8`).\n5. If it points to the router, log into the router and ensure its WAN DNS settings are valid.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-155", title: "Adding an unmanaged switch causes the entire office network to slow down or drop randomly.", content: "1. A network loop has been created.\n2. Someone likely plugged a cable from Port 1 of the unmanaged switch into Port 2 of the same switch, or plugged both ends of a long cable into two different wall jacks that terminate on the same switch.\n3. Spanning Tree Protocol (STP) should block this, but unmanaged switches don't support STP.\n4. Find the physical loop and unplug one end immediately.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-156", title: "D-Link Access Point's SSID is not broadcasting (hidden), and users cannot connect.", content: "1. If it was intentionally hidden, users must manually type in the SSID to connect.\n2. If it was not supposed to be hidden, log into the D-Link AP via its IP address.\n3. Go to Wireless -> Basic Settings.\n4. Ensure \"Enable Wireless\" and \"Enable SSID Broadcast\" are both checked.\n5. If the settings are correct but it's still not broadcasting, factory reset the AP; the radio may have failed.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-157", title: "Cannot access the router's management page at 192.168.1.1, but the internet works.", content: "1. Your PC might be on a different subnet, or the router uses a different IP.\n2. Open CMD, type `ipconfig`.\n3. Look at the \"Default Gateway\" for your active adapter; that is the router's actual IP (it might be `10.0.0.1` or `192.168.0.1`).\n4. If you still can't access it, the router's admin interface might be accessible only via a specific VLAN or the \"Remote Management\" feature is turned off.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-158", title: "VoIP phones sound choppy or drop calls when a large file is being downloaded.", content: "1. There is no QoS (Quality of Service) configured.\n2. Log into the managed switch.\n3. Access the QoS settings.\n4. Set the VoIP VLAN to the highest priority (DSCP EF / CS5).\n5. Ensure the port connected to the IP phone trusts the DSCP markings from the phone.\n6. This forces the switch to process voice packets before bulk data packets.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-159", title: "PoE (Power over Ethernet) switch is not powering an IP camera or VoIP phone.", content: "1. The device likely exceeds the switch's PoE budget.\n2. Check the switch's total PoE wattage (e.g., 120W total).\n3. If all ports are full, you may have exceeded this.\n4. Alternatively, the cable run might be too long (PoE drops voltage over 100m/328ft).\n5. Run `show power inline` on a Cisco switch to see if the port is in \"Fault\" or \"Power Denied\" state.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-160", title: "Network share mapping (`net use`) fails with \"System error 1219 has occurred\" when connecting to a second server.", content: "1. Windows limits one set of credentials per remote server.\n2. If you mapped a drive to `ServerA` as `User1`, and try to map to `ServerB` as `User2` (or even a different\n3. share on `ServerA` with different creds), it fails.\n4. Disconnect all existing drives: `net use * /delete /y`. Reconnect using the exact same credentials for all shares on that server, or use the IP address instead of the hostname for the second connection.", category: "Networking & WiFi", tags: ["networking","wifi","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-161", title: "Fiber Optic ONT (Optical Network Terminal) shows a solid or flashing RED \"LOS\" (Loss of Signal) light.", content: "1. Do not unplug the fiber cable.\n2. A red LOS light means the fiber optic cable is broken, bent too sharply, or disconnected at the pole/outside box.\n3. Check the thin fiber cable inside the house for severe kinks or pet damage.\n4. If the indoor cable looks fine, contact the ISP immediately; a technician must splice or replace the exterior drop cable.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-162", title: "VDSL/ADSL modem constantly loses sync, and the \"DSL\" light blinks or turns red multiple times a day.", content: "1. The copper line has noise, water in the lines, or is too far from the DSLAM.\n2. Log into the modem at `192.168.1.254`.\n3. Check the \"Line Attenuation\" (should be under 40dB) and \"SNR Margin\" (should be above 6dB, ideally 12dB).\n4. If SNR is low, unplug all other devices from the phone jacks in the house (alarm systems, fax machines) and replace the DSL micro-filters.\n5. If it persists, call the ISP to test the copper line.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-163", title: "Business pays for a 500Mbps Fiber plan, but speed tests only show 100Mbps.", content: "1. Ensure you are testing via a hardwired Ethernet cable, not WiFi.\n2. Check the lights on the ONT/Router port; if the LED is green, it's 100Mbps.\n3. If it's blue/amber, it's 1Gbps.\n4. If it's green, your router or PC is negotiating at 100Mbps.\n5. Replace the Cat5 cable with a Cat5e or Cat6 cable.\n6. Also, ensure the ISP hasn't mistakenly provisioned a 100Mbps profile on their end.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-164", title: "Router shows \"PPPoE Authentication Failed\" and there is no internet.", content: "1. The router failed to log into the ISP using the provided username and password.\n2. Log into the router's WAN settings.\n3. Re-type the PPPoE credentials exactly as provided by the ISP (case-sensitive).\n4. If the credentials are correct, the ISP may have suspended the account or reset the password.\n5. Call the ISP billing/tech support to verify the PPPoE credentials are active.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-165", title: "4G/LTE Router shows full signal bars but has zero data throughput (no internet).", content: "1. The router is connected to the cell tower but not authenticated for data.\n2. Check the APN (Access Point Name) settings in the router's mobile settings.\n3. Ensure the APN matches the ISP's exact string (e.g., `broadband` or `internet`).\n4. If the APN is correct, the SIM card may be out of data, blocked, or not provisioned for router use (many ISPs block tethering/routers on phone SIMs).", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-166", title: "Leased Line experiences high latency (ping spikes from 10ms to 300ms) randomly throughout the day.", content: "1. Leased lines should have guaranteed SLAs and zero packet loss.\n2. Do not reboot the router; it will clear the logs.\n3. SSH into the edge router and run a continuous ping to the ISP's gateway (`ping x.x.x.x -t`).\n4. When the spike happens, immediately contact the ISP NOC (Network Operations Center) and provide the exact time of the spike.\n5. They will check their MPLS cloud for congestion or a flapping interface.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-167", title: "DNS resolution fails intermittently, but pinging IP addresses works perfectly.", content: "1. The ISP's default DNS servers are overloaded or failing.\n2. Log into your router's WAN/DHCP settings.\n3. Change the primary and secondary DNS servers handed out to clients from the ISP's defaults to `1.1.1.1` (Cloudflare) and `8.8.8.8` (Google).\n4. This entirely bypasses the ISP's faulty DNS resolvers.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-168", title: "Starlink or Satellite internet is completely unusable for Zoom/Teams calls.", content: "1. Physics: Satellite internet has a minimum latency of ~500-700ms due to the distance to space.\n2. Video conferencing requires <150ms.\n3. There is no technical fix for the speed of light.\n4. The only resolution is to switch to a terrestrial connection (Fiber/Cable/4G) for real-time communication, and use the satellite strictly for bulk downloads/uploads.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-169", title: "Dual-WAN failover router fails to switch to the backup 4G connection when the primary Fiber goes down.", content: "1. The router's health check settings are misconfigured.\n2. Log into the dual-WAN router.\n3. Go to Failover settings.\n4. The \"Health Check\" method cannot just be \"Ping ISP Gateway\" (because the local gateway might still be up even if the WAN is dead).\n5. Change the Health Check target to `8.8.8.8` or `1.1.1.1`.\n6. Reduce the failure threshold (e.g., fail after 3 consecutive failed pings).", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-170", title: "Outbound emails from the company server are being rejected by external domains with \"Relay Access Denied\" or \"Blocked by ISP\".", content: "1. Port 25 is likely blocked by the ISP, or the IP lacks reverse DNS (PTR record).\n2. First, test if port 25 is blocked: open CMD, `telnet alt1.gmail.com 25`.\n3. If it fails, call the ISP and request Port 25 unblocking (often requires a business account).\n4. Second, ask the ISP to create a PTR (Reverse DNS) record pointing your static public IP to your mail domain (e.g., `mail.yourdomain.com`).", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-171", title: "ISP-provided modem/router gets extremely hot to the touch and drops internet every few hours.", content: "1. The ISP hardware is thermally throttling.\n2. Do not block the router's vents.\n3. Ensure at least 3 inches of clearance on all sides.\n4. If the issue persists, call the ISP and report the hardware is overheating.\n5. Request a replacement modem.\n6. As a temporary IT workaround, place a small USB-powered fan next to the router's vents to force hot air out.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-172", title: "I want to use my own Cisco/Ubiquiti router, but the ISP says I must use their \"Fiber Gateway\".", content: "1. Put the ISP gateway into \"Bridge Mode\" or \"IP Passthrough\".\n2. Log into the ISP gateway (e.g., 192.168.1.254).\n3. Look for \"Advanced Setup\" -> \"Bridge Mode\".\n4. This disables the ISP router's WiFi, DHCP, and NAT, turning it into a pure modem.\n5. Then, plug the ISP gateway into the WAN port of your own router, and your router will handle the public IP via PPPoE or DHCP.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-173", title: "Remote users cannot connect to the office VPN, which is behind a residential ISP connection.", content: "1. The ISP is using Carrier-Grade NAT (CGNAT), meaning the office does not have a real public IP address, making inbound VPN connections impossible.\n2. Upgrade to a Business ISP plan to get a static public IP, use a VPN service that supports NAT Traversal (like Tailscale or WireGuard with a relay node), or have the router initiate an outbound VPN tunnel to a cloud server.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-174", title: "Internet drops completely, but only when it rains or during high humidity.", content: "1. Water is infiltrating an outdoor junction box or the ISP's outdoor cabling.\n2. If on DSL/Copper, moisture shorts out the exposed copper pairs.\n3. If on Fiber, water refracts the laser light causing LOS.\n4. Call the ISP and explicitly state: \"The connection drops when it rains.\" They will dispatch a line technician to reseal the outdoor pedastal or drop cable.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-175", title: "Running a Tracert shows the first hop (the router) timing out with `* * * Request timed out`.", content: "1. This is almost always normal.\n2. Most routers (including Cisco and ISP edge routers) are configured to prioritize routing traffic over responding to ICMP (ping/tracert) requests from external or local sources.\n3. As long as the trace eventually reaches the destination (e.g., google.com at hop 10), the first hop timing out is not an error.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-176", title: "Certain websites fail to load completely (stuck at loading), while others load instantly.", content: "1. This is an MTU (Maximum Transmission Unit) Black Hole issue.\n2. The path to that specific website has a lower MTU, and a firewall is dropping the fragmented packets.\n3. Open CMD as admin and run: `netsh interface ipv4 show subinterfaces`.\n4. Note the MTU (usually 1500).\n5. Lower it by running: `netsh interface ipv4 set subinterface \"Ethernet\" mtu=1400 store=persistent`.\n6. Try loading the site again.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-177", title: "How do I test a new Business Leased Line handoff before connecting the edge router?", content: "1. Use a laptop with a static IP configuration.\n2. Set the laptop's IP to the ISP's provided usable IP, subnet mask, and gateway.\n3. Plug the laptop directly into the ISP's handoff cable (RJ45).\n4. Ping the gateway.\n5. If successful, ping an external IP (like `8.8.8.8`).\n6. If that works, the ISP handoff is physically and logically live and ready for your edge router.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-178", title: "Site-to-Site VPN goes down daily because the ISP changes the branch office's public IP address.", content: "1. The branch is on a dynamic IP.\n2. You cannot use static IP VPN configurations.\n3. Convert the branch router's VPN to a \"Dynamic DNS\" (DDNS) setup (e.g., using `branch.no-ip.com`).\n4. Better yet, if both sites use the same router brand (e.g., MikroTik or Ubiquiti), ditch traditional IPsec and use a mesh VPN protocol like WireGuard or Tailscale, which handles dynamic IPs natively without dropping the tunnel.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-179", title: "Coaxial cable modem (Cable Internet) logs show \"T3 Timeout\" or \"T4 Ranging\" errors, causing internet drops.", content: "1. These errors mean the modem is losing communication with the ISP's CMTS (Cable Modem Termination System) due to poor signal.\n2. Log into the modem (usually `192.168.100.1`).\n3. Check \"Downstream Power Level\" (should be between -7 to +7 dBmV) and \"Upstream Power Level\" (should be between 35 to 49 dBmV).\n4. If outside these ranges, tighten the coax cables, remove any splitters, or call the ISP to boost the line signal.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-180", title: "I cannot access the ISP modem's GUI (192.168.100.1) because it is behind my own router.", content: "1. Your router's WAN port and the ISP modem's LAN port are on different subnets, and your router drops inbound requests from the WAN.\n2. To access it, plug a laptop directly into the ISP modem's LAN port (bypassing your router) and set the laptop to DHCP.\n3. Alternatively, if you have a managed switch, put the modem and a laptop on an untagged VLAN that bypasses the router.", category: "Internet & ISP", tags: ["internet","isp","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-181", title: "Cisco AnyConnect fails with \"The service provider in your current location is restricting access\" immediately.", content: "1. This means the local ISP or firewall (often in countries with strict censorship or on corporate guest networks) is blocking the default Cisco TLS port (TCP 443).\n2. Create a backup profile in the AnyConnect XML file (`AnyConnectProfile.xml`) under `` and add an alternative host or port (e.g., TCP 4433) configured on the ASA headend.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-182", title: "FortiGate IPsec VPN tunnel goes up, but throughput is incredibly slow (e.g., 10Mbps on a 1Gbps line).", content: "1. IPsec hardware offloading is failing, forcing the FortiGate's CPU to encrypt traffic in software.\n2. SSH into the FortiGate and run `diagnose debug application ike -1` and `diagnose debug enable`.\n3. Look for \"kernel crypto\" messages.\n4. Ensure the phase 1/2 proposals do not include algorithms unsupported by the NPU/CP9 ASIC chips (e.g., avoid AES-GCM if offloading fails, or upgrade FortiOS).", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-183", title: "Palo Alto GlobalProtect fails user authentication with \"Authentication failed due to invalid credentials\", but the password is correct.", content: "1. The firewall's local certificate used for SSL decryption or the SAML certificate has expired, or there is a time-sync issue.\n2. Verify the Palo Alto's NTP server is syncing (`show system time`).\n3. If using SSO/SAML, check the certificate on the IdP (like Okta/Entra) to ensure it hasn't expired, and that the Assertion Consumer Service (ACS) URL matches the GlobalProtect portal exactly.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-184", title: "OpenVPN client connects successfully, but the user cannot access local LAN resources (like their home printer).", content: "1. This is a missing or incorrect split-tunneling configuration.\n2. On the OpenVPN server config, ensure `push \"route 192.168.1.0 255.255.255.0 net_gateway\"` is added (replacing with the user's home subnet).\n3. Additionally, ensure the client config does NOT have `redirect-gateway def1`, which forces all traffic (including local) through the VPN.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-185", title: "WireGuard VPN shows \"Handshake did not complete\" in the interface logs.", content: "1. WireGuard uses UDP, so stateful firewalls often drop the packets.\n2. Ensure the firewall allows inbound/outbound UDP on the specified port (e.g., 51820).\n3. If the server is behind NAT, ensure port forwarding is set up correctly.\n4. Finally, verify the `Endpoint` IP in the client config is the server's *public* IP, not its internal IP, and that the `AllowedIPs` includes the server's tunnel IP.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-186", title: "Users can connect to the VPN, but large file transfers fail or remote desktop sessions freeze, while ping works fine.", content: "1. This is a classic Path MTU Discovery (PMTUD) black hole.\n2. The VPN encapsulation adds overhead, making packets too large for the physical network, and ICMP \"Fragmentation Needed\" messages are blocked.\n3. Fix this on the firewall/router by enabling MSS Clamping.\n4. In Linux (iptables): `iptables -t mangle -A FORWARD -p tcp --tcp-flags SYN,RST SYN -j TCPMSS -clamp-mss-to-pmtu`.\n5. On FortiGate, it's enabled by default but can be verified under VPN settings.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-187", title: "Cisco AnyConnect connects, but internal DNS resolution for `server.local` fails.", content: "1. The VPN profile is not pushing the correct DNS suffix.\n2. Edit the ASA configuration (or the XML profile) and ensure `split-dns` is configured with the internal domain name (e.g., `split-dns yourdomain.local`).\n3. Also ensure `dns-server` is set to the internal Domain Controller's IP under the group-policy assigned to the users.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-188", title: "Multiple remote users behind the same hotel/conference NAT cannot connect to FortiGate SSL VPN simultaneously.", content: "1. The FortiGate is confusing the sessions because the source IP and port are identical for multiple users.\n2. Enable NAT-T (NAT Traversal) on the FortiGate SSL VPN settings.\n3. Alternatively, switch the SSL VPN portal from \"Tunnel Mode\" to \"Web Mode\" for these specific users, as web mode proxies the connection from the firewall itself.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-189", title: "GlobalProtect portal is unreachable from the internet, but internal testing works perfectly.", content: "1. The perimeter firewall (in front of the Palo Alto) is blocking the GlobalProtect ports.\n2. GlobalProtect requires TCP 443 (for the portal/gateway) and UDP 4500 (for IPsec).\n3. Ensure the public NAT rule translates the public IP to the interface IP of the Palo Alto, and that the security policy allows traffic to the zone where the GlobalProtect interface resides.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-190", title: "OpenVPN client receives an IP address, but has no network access to the server's LAN.", content: "1. IP forwarding is disabled on the OpenVPN server OS.\n2. If Linux, run `sysctl -w net.ipv4.ip_forward=1` and make it permanent in `/etc/sysctl.conf`.\n3. Additionally, ensure the firewall on the OpenVPN server (e.g., UFW or iptables) allows traffic to be forwarded between the `tun0` interface and the `eth0` interface, and that a POSTROUTING MASQUERADE rule exists.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-191", title: "AnyConnect fails with \"Untrusted VPN Server Blocked\" when connecting to a new ASA cluster.", content: "1. The new ASA's public SSL certificate does not match the hostname the client is configured to use, or the issuing CA is not in the user's Trusted Root Certificate store.\n2. Either install a public SSL cert (like Let's Encrypt/DigiCert) on the ASA, or deploy the internal Root CA via Active Directory Group Policy to all client machines.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-192", title: "FortiGate Route-based VPN is up, but routing protocols (OSPF/BGP) over the VPN are not forming adjacencies.", content: "1. By default, FortiGate route-based VPN interfaces (`vpn0`) have MTU set to 0 (which defaults to 1500, too large for IPsec).\n2. Reduce the MTU on the VPN interface to 1400.\n3. Also, ensure multicast traffic is allowed in the firewall policy binding the local network to the VPN tunnel interface.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-193", title: "GlobalProtect crashes the Windows client laptop with a Blue Screen (BSOD) immediately upon connecting.", content: "1. The GlobalProtect virtual network adapter is conflicting with a third-party software (often other VPNs like Cisco, or aggressive Antivirus like CrowdStrike).\n2. Boot into Safe Mode, uninstall GlobalProtect.\n3. Run `devcon.exe` (Windows Driver Kit) or Device Manager to \"Show hidden devices\" and manually delete the leftover `PanGPA` or `Wintun` adapters.\n4. Reinstall the latest GlobalProtect version.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-194", title: "WireGuard tunnel drops exactly every 3-5 minutes when idle.", content: "1. The client is behind a NAT router that aggressively drops idle UDP states.\n2. Add the `PersistentKeepalive = 25` directive under the `[Peer]` section of the client's WireGuard config file.\n3. This sends a tiny ping every 25 seconds to keep the NAT port mapping open on the client's router.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-195", title: "AnyConnect service will not start; Windows Services shows \"Error 87: The parameter is incorrect.\"", content: "1. The VPN filter driver (like `vpnva.sys`) is corrupted.\n2. Open Registry Editor (`regedit`) and navigate to `HKEY_LOCAL_MACHINE\\SYSTEM\\ CurrentControlSet\\Services\\vpnva`.\n3. Change the `Start` value to `4` (Disabled).\n4. Reboot the PC.\n5. The AnyConnect service should now start.\n6. Uninstall AnyConnect completely, reboot again, and reinstall a fresh copy.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-196", title: "IPsec Site-to-Site VPN fails Phase 1 with \"No proposal chosen\" error.", content: "1. The encryption/hash algorithms or Diffie-Hellman (DH) groups do not match between the two firewalls.\n2. Check both sides.\n3. Ensure both have matching Phase 1 proposals (e.g., AES256-SHA256-DH14).\n4. If one side is set to \"Default\" and the other is \"Custom\", explicitly define the exact same custom proposals on both sides.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-197", title: "Split-tunnel VPN allows access to internal servers, but internet browsing through the VPN is extremely slow.", content: "1. Traffic is hairpinning.\n2. The VPN client sends internet traffic to the office firewall, but the office firewall sends its outbound traffic out the same interface it came in on, bypassing hardware offloading.\n3. Fix by ensuring the firewall's internet-bound routing table points out the correct WAN interface, not the VPN interface, or enable asymmetric routing support on the perimeter router.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-198", title: "OpenVPN client logs show \"TLS Error: TLS key negotiation failed to occur within 60 seconds.\"", content: "1. The client cannot reach the server on the specified port, or the firewall is dropping the traffic.\n2. Verify the server's firewall allows UDP/TCP on the OpenVPN port.\n3. If the server is in AWS/Azure, ensure the Network Security Group (NSG) allows the inbound port.\n4. If using TCP 443, ensure no other web server (IIS/Apache) is already binding to 0.0.0.0:443 on the VPN server.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-199", title: "AnyConnect fails \"Posture Assessment\" requiring \"AnyConnect Protected Network\" or missing Antivirus.", content: "1. The ASA is enforcing a Host Scan/Posture profile.\n2. Ensure the user's Windows Defender or corporate AV service is running (`services.msc`).\n3. If they are on a personal PC, they will be blocked unless the admin creates a separate \"Less Secure\" group policy that does not require posture compliance for BYOD users.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-200", title: "WireGuard site-to-site tunnel works for some subnets but not others ( asymmetric routing ).", content: "1. The `AllowedIPs` directive is incorrect.\n2. On Server A, `AllowedIPs` must include the *remote* subnet of Server B (e.g., `10.0.1.0/24`), and on Server B, it must include the subnet of Server A (e.g., `10.0.0.0/24`).\n3. If you accidentally include the local subnet in `AllowedIPs`, WireGuard will drop the packets to prevent routing loops.", category: "VPN & Remote Access", tags: ["vpn","remote","access","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-201", title: "Hikvision IP camera shows \"Network Abnormal\" or goes offline randomly throughout the day.", content: "1. IP conflicts or PoE budget exhaustion.\n2. Run the Hikvision SADP tool to ensure no other device has claimed the camera's IP.\n3. Check the PoE switch's total wattage; if 4 cameras draw 15W each (60W) but the switch is only 30W, it will power-cycle the cameras.\n4. Upgrade to a high-wattage PoE+ switch or use midspan injectors.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-202", title: "Dahua NVR shows \"No Video\" on a specific channel, but the camera is powered and online.", content: "1. The NVR's \"Plug & Play\" protocol has desynced.\n2. Log into the NVR GUI -> System Setup -> Network Setup -> P2P/Plug & Play.\n3. Turn it OFF.\n4. Manually add the camera by going to Remote Device -> Add, typing the camera's IP, port (37777), and the admin password.\n5. Ensure the protocol is set to \"Dahua\" rather than ONVIF.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-203", title: "Axis camera image is completely washed out or white during daylight hours.", content: "1. The IR cut filter is stuck or the WDR (Wide Dynamic Range) is failing.\n2. Log into the Axis web UI -> Video -> Image Appearance.\n3. Ensure WDR is set to \"Wide Dynamic Range\" and the level is adjusted.\n4. If still white, the physical IR cut filter mechanical switch inside the camera has failed, requiring an RMA.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-204", title: "Night vision is completely black, even though the camera's IR LEDs are visibly glowing red.", content: "1. A spider web or a piece of debris is resting directly in front of the IR LEDs.\n2. The IR light reflects off the web right back into the camera lens, blinding the sensor.\n3. Physically clean the camera dome/lens with a microfiber cloth.\n4. If the issue persists, adjust the camera angle slightly downward so the IR beam doesn't hit nearby walls.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-205", title: "NVR hard drive shows as \"Uninitialized\" and is not recording.", content: "1. Surveillance NVRs require disks to be formatted in a proprietary Linux file system (like ext4 with specific offsets).\n2. Log into the NVR GUI -> System Setup -> Disk Management.\n3. Select the uninitialized drive and click \"Format\".\n4. Warning: This wipes all existing data.\n5. Only use surveillance-grade drives (WD Purple, Seagate SkyHawk); standard desktop drives will fail quickly.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-206", title: "Remote viewing via Hikvision iVMS-4200 or Hik-Connect app fails with \"Device Offline\" externally, but works on local LAN.", content: "1. Port forwarding is missing or blocked by the ISP (many block port 80/8080).\n2. On the router, forward TCP 8000 (HTTP), TCP 8443 (HTTPS), and TCP 37777 (Data) to the NVR's internal IP.\n3. If the ISP blocks these, use the Hik-Connect P2P feature (ensure \"Platform Access\" is enabled in the NVR's Network settings) which bypasses port forwarding via cloud relay.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-207", title: "CP Plus DVR shows horizontal rolling lines or video tearing on all channels.", content: "1. This is a ground loop issue caused by voltage differences between the DVR and the cameras.\n2. Install passive CCTV ground loop isolators on the BNC cables at the back of the DVR.\n3. If using UTP cable with Baluns, ensure the Baluns are powered from the same source as the DVR, or run a dedicated ground wire between the camera housings and the DVR chassis.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-208", title: "Hanwha camera pixelates heavily when there is fast motion (cars driving by).", content: "1. The bitrate is configured as VBR (Variable Bit Rate) and cannot spike fast enough during motion.\n2. Log into the camera's web UI -> Setup -> Network -> Stream.\n3. Change the bitrate type from VBR to CBR (Constant Bit Rate).\n4. Increase the bitrate to at least 4096 Kbps (4Mbps) for 1080p, or 8192 Kbps for 4K.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-209", title: "Dahua NVR interface is incredibly slow, lagging by 10-20 seconds when clicking menus.", content: "1. The NVR's system drive is failing, causing massive I/O wait times for the embedded Linux OS.\n2. SSH into the NVR (if enabled) or check the System Logs -> Disk Logs for \"Read/Write Error\" or \"Bad Sector\" messages.\n3. Replace the primary HDD/SSD immediately and re-flash the NVR firmware.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-210", title: "User forgot the admin password for an Axis camera and is completely locked out.", content: "1. Axis cameras have a physical reset button.\n2. Unplug the PoE cable.\n3. Press and hold the reset button (usually a small pinhole next to the network port).\n4. While holding it, plug the PoE back in.\n5. Hold for 15-30 seconds until the status LED turns amber.\n6. The camera will reset to `192.168.1.1` with a blank password.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-211", title: "Motion detection triggers hundreds of false alarms at night due to insects.", content: "1. Insects reflect IR light.\n2. Log into the camera GUI -> Event -> Video Detection -> Motion Detection.\n3. Draw a \"Privacy Mask\" or \"Region of Interest\" to ignore the bottom 10% of the screen where insects fly.\n4. Additionally, change the camera to \"Smart Event\" (Human/Vehicle detection) rather than basic pixelchange motion detection.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-212", title: "Hikvision NVR is not recording during specific hours despite continuous 24/7 schedule being set.", content: "1. Check the NVR's \"Disk Full\" settings.\n2. If the disk reached 100% capacity, the NVR may be set to \"Stop Recording\" rather than \"Overwrite\".\n3. Go to System Setup -> Disk Management -> Disk Full Policy.\n4. Change it to \"Overwrite\" (Overwrite oldest footage when full).\n5. Also verify the NVR's internal clock is correct.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-213", title: "PTZ (Pan-Tilt-Zoom) camera moves uncontrollably or \"hunts\" when trying to auto-track an object.", content: "1. The auto-tracking sensitivity is too high, or the firmware has a bug.\n2. Log into the PTZ menu.\n3. Reduce the \"Sensitivity\" and \"Zoom Speed\" under Smart Tracking settings.\n4. Update the PTZ firmware to the latest version.\n5. If it still hunts, disable \"Auto Flip\" and set hard zoom limits so the camera doesn't try to look directly down.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-214", title: "Email alerts for motion detection are not being received by the security team.", content: "1. Modern email providers (Gmail, Office 365) block basic SMTP authentication.\n2. Log into the NVR/Camera -> Network -> SMTP.\n3. Ensure the SMTP server is set to `smtp.office365.com` (port 587, TLS) or `smtp.gmail.com` (port 465, SSL).\n4. You MUST use an \"App Password\" or a dedicated service account, not a standard user password.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-215", title: "Integrating a 3rd party ONVIF camera into a Hikvision NVR results in a \"Protocol Mismatch\" or no video.", content: "1. Hikvision heavily favors its proprietary protocol.\n2. Log into the Hikvision NVR -> System Setup -> Network Setup -> Basic Config -> Check \"Enable ONVIF\".\n3. When adding the camera, change the protocol from \"Hikvision\" to \"ONVIF\".\n4. Ensure the ONVIF port (usually 80 or 8080) is open on the 3rd party camera, and enter the camera's ONVIF user credentials (sometimes different from the admin credentials).", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-216", title: "Camera image has a pink, purple, or green tint that won't go away.", content: "1. The camera's white balance is stuck, or the sensor is failing.\n2. Go to the video settings and set White Balance from \"Auto\" to \"Manual\", then set it to \"Outdoor\" or \"Indoor\" depending on the environment.\n3. If the tint remains, perform a factory reset.\n4. If it's still tinted, the CMOS sensor is permanently damaged (often due to direct sunlight exposure or power surge) and needs replacement.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-217", title: "NVR GUI is accessible, but the \"Playback\" tab is greyed out or shows no timeline data.", content: "1. The NVR user account being used does not have \"Playback\" permissions.\n2. Log out and log in as the `admin` account.\n3. Go to System Setup -> User Management -> Edit the user's permissions.\n4. Ensure \"Remote Playback\" and \"Local Playback\" are checked.\n5. If using an Active Directory integration, ensure the AD security group has been granted playback rights in the NVR.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-218", title: "Video feed from a camera at the end of a 300m CAT6 cable is pixelated or drops out.", content: "1. The maximum distance for standard PoE over CAT6 is 100 meters (328 feet).\n2. At 300m, signal attenuation is severe.\n3. Install an IP PoE Extender (injector) at the 100m mark, which repeats the signal and injects fresh power.\n4. Alternatively, run fiber optic cable with media converters to the remote camera.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-219", title: "Dahua DVR prompts for a \"Secure Code\" that the installer never wrote down.", content: "1. Dahua requires a security code to export/modify settings.\n2. If lost, you can bypass it using the Dahua Password Reset Tool (DMSS or local app).\n3. You must generate a reset file on `dahuasecurity.com` using the DVR's exact model and MAC address, load it onto a USB stick, and plug it into the DVR's front USB port to reset the admin password.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-220", title: "Live view works locally, but Hik-Connect P2P cloud access says \"Device is sleeping\" or \"Offline\".", content: "1. The NVR is blocking outgoing cloud traffic.\n2. Ensure the NVR's DNS is set to `8.8.8.8` (it cannot resolve Hik-Connect servers if using a local DC).\n3. Go to Network -> Advanced -> Platform Access.\n4. Ensure \"Enable\" is checked.\n5. If it says \"Inactive\", click \"Deactivate\" and then \"Activate\" to force a new handshake with the Hik-Connect cloud servers.", category: "CCTV & Surveillance", tags: ["cctv","surveillance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-221", title: "HID iCLASS card reader beeps and flashes green, but the door's maglock does not unlock.", content: "1. The reader is sending the Wiegand signal to the access control panel, but the panel is not sending 12V/24V to the lock.\n2. Check the power supply to the lock.\n3. If it's a Fail-Secure lock, it requires power *to unlock*. Check if the relay on the control board is burnt out by using a multimeter to check for voltage across the lock terminals when a valid card is presented.\n4. Replace the 12VDC power supply or relay if dead.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-222", title: "Suprema fingerprint reader gives \"Access Denied\" for a user whose fingerprint previously worked fine.", content: "1. Finger condition changes (dry skin, cuts, dirt).\n2. Do not delete the enrollment yet.\n3. Have the user wash their hands and use their secondary enrolled finger.\n4. If it still fails, log into BioStar 2, go to the User settings, and increase the \"Security Level\" (False Acceptance Rate) from \"Normal\" to \"Low\" temporarily.\n5. Re-enroll the finger using multiple angles (flat, slight roll left/right).", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-223", title: "ZKTeco keypad reader does not read HID cards, but PIN codes work perfectly.", content: "1. Wiegand data format mismatch.\n2. The reader might be outputting 37-bit HIDCorporate1000 format, but the ZKTeco controller is expecting standard 26-bit Wiegand.\n3. Use the ZKTeco setup utility (ZKAccess) to change the Wiegand format on the reader input port to match the exact format of the HID cards (usually 26-bit).\n4. If the reader is hardwired for 37-bit, you may need a different reader model.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-224", title: "Paxton Net2 system triggers a \"Tamper\" alarm on a specific door, locking it down.", content: "1. The physical tamper switch on the back of the reader or control unit is not seated correctly against the backbox, or the screw is loose.\n2. Open the reader casing.\n3. Ensure the plastic tamper peg is pressing firmly against the spring switch on the PCB.\n4. Tighten the mounting screws.\n5. Clear the alarm in the Paxton Net2 software.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-225", title: "Smart Lock (e.g., August/Schlage Encode) keeps going offline in the management app.", content: "1. Smart locks rely on Bluetooth to bridge to a WiFi hub.\n2. If the lock is far from the hub, it drops offline.\n3. Move the WiFi bridge closer to the door (within 10-15 feet, line of sight).\n4. If it's battery-powered, check the battery level; low voltage disables the WiFi radio to conserve power for the motor.\n5. Replace CR123A or AA batteries.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-226", title: "New employee's HID card was added to the software, but they still get \"Access Denied\".", content: "1. The software database is not synced to the physical door controller.\n2. In Paxton, right-click the control unit and select \"Synchronize\".\n3. In HID Edge/EH controllers, ensure the \"Online\" status is green.\n4. If offline, check the TCP/IP connection or serial connection to the door controller.\n5. The controller operates independently; if it doesn't receive the update, the card fails.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-227", title: "Suprema FaceStation facial recognition fails when the user is wearing a mask or sunglasses.", content: "1. Legacy firmware requires the full face.\n2. Update the FaceStation firmware to the latest \"Deep Learning\" AI version, which supports masked face recognition.\n3. In BioStar 2, go to Device -> Face Setup -> Enable \"Mask Mode\" or lower the facial threshold score.\n4. Re-enroll the user's face to capture the new AI biometric templates.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-228", title: "ZKTeco inBio controller shows \"Error 06\" or continuously beeps and doesn't unlock the door.", content: "1. Error 06 on ZKTeco usually indicates a communication failure between the reader and the inBio controller via RS485.\n2. Check the TX/RX and GND wires.\n3. Ensure you are using a daisy-chain topology (parallel), not a star topology.\n4. Verify the terminating resistor (120-ohm) is installed across the Data+ and Data- terminals at the *last* reader in the chain.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-229", title: "Door releases when a valid card is presented, but immediately re-locks, trapping the user inside.", content: "1. The REX (Request to Exit) motion sensor inside the room is broken, or the door magnetic contact thinks the door never opened.\n2. Bypass the door contact temporarily in the access panel settings to allow entry.\n3. Test the REX sensor by waving your hand in front of it; if the REX LED doesn't light up, replace the PIR motion sensor or check its 12V power.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-230", title: "Electric strike buzzes loudly and gets extremely hot after unlocking.", content: "1. The strike is a \"Fail-Secure\" model, meaning it is constantly drawing power to stay locked.\n2. When it unlocks, it holds the solenoid open.\n3. If it's hot, it's either the wrong voltage (e.g., 12V strike on a 24V power supply) or it's being held in the \"unlocked\" state too long via software.\n4. Ensure the power supply matches the lock's voltage exactly, and set the door to \"Lock After 5 Seconds\" in the access software.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-231", title: "Paxton Net2 software shows \"Communication Lost\" with a specific door controller over the network.", content: "1. The Paxton Net2 control unit's IP address changed via DHCP.\n2. Connect a laptop directly to the controller's LAN port, set your laptop to `192.168.1.10`, and access the controller's web GUI at `192.168.1.1`.\n3. Change the controller's IP to a static IP outside the DHCP pool, matching the subnet of the main network.\n4. Re-ping from the server.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-232", title: "HID card cloning detected: An unauthorized person used a cloned card to gain entry.", content: "1. Legacy 125kHz Prox or older iCLASS cards are vulnerable to cloning.\n2. Immediate action: Delete the compromised credential from the system.\n3. Long-term fix: Migrate to highly encrypted credentials like HID iCLASS SE or Seos, which use AES-128 bit encryption and mutual authentication, making them virtually impossible to clone via standard RF attacks.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-233", title: "Suprema Xpass reader LCD screen is flickering or displaying garbled text.", content: "1. This is caused by electromagnetic interference (EMI) from the lock cable running parallel to the reader cable.\n2. The 12V/24V AC/DC power spikes to the maglock are bleeding into the reader's data line.\n3. Separate the lock power cables from the reader communication cables by at least 2 inches.\n4. If already separated, install a diode (flyback diode) across the lock terminals to suppress voltage spikes.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-234", title: "ZKTeco time & attendance terminal is not pushing data to the central SQL server.", content: "1. Check the IP and Port (usually 4370) configuration in the ZKTeco device.\n2. Open CMD on the server and run `telnet [Device_IP] 4370`.\n3. If it fails, a firewall is blocking UDP/TCP 4370.\n4. Add an inbound rule in Windows Defender Firewall for port 4370.\n5. Also verify the SQL connection string in ZKAccess is using the correct SQL authentication credentials.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-235", title: "User gets \"Anti-Passback Violation\" when trying to enter, but they definitely swiped out earlier.", content: "1. The exit reader failed to read their card, or they tailgated out.\n2. Do not disable Anti-Passback globally (it's a security feature).\n3. In the access software (e.g., Win-Pak, Net2), locate the user's profile and clear their \"Zone Status\" or \"AntiPassback State\" to reset them to \"Outside\".\n4. Instruct the user to ensure they tap their card on the exit reader, even if the door is held open.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-236", title: "Smart lock keypad is completely unresponsive to touch or button presses.", content: "1. Moisture ingress or extreme cold has frozen the capacitive touch layer.\n2. Remove the interior cover of the lock and check for condensation.\n3. Dry the PCB with compressed air.\n4. If the lock is in sub-zero temperatures, use a lock de-icer or a heat gun on a LOW setting to warm the exterior keypad.\n5. If it remains dead, the keypad membrane is permanently shorted.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-237", title: "During a fire alarm test, the access control doors remained locked, violating fire code.", content: "1. CRITICAL LIFE SAFETY VIOLATION.\n2. Fire Alarm Relay (FAR) connections are wrong or missing.\n3. The fire panel must have a dry-contact relay wired to the access control panel's \"Emergency Release\" or \"Fire Interface\" inputs.\n4. When the fire panel trips, it breaks the circuit, forcing the access panel to drop power to ALL failsafe locks.\n5. Verify the wiring and test immediately.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-238", title: "Paxton Paxton10 system will not discover a newly wired Net2 nano controller.", content: "1. The nano controller is in \"Boot mode\" or not assigned to the site.\n2. Ensure the nano is connected to the network and the power LED is solid.\n3. In Paxton10, go to System -> Unregistered Devices.\n4. If it doesn't appear, press and hold the reset button on the nano for 10 seconds until the LED flashes amber.\n5. It will then broadcast for discovery.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-239", title: "Mobile credential (Apple Wallet / Smartphones) fails to unlock a HID iCLASS SE reader.", content: "1. The reader must specifically support OSDP (Open Supervised Device Protocol) over BLE (Bluetooth Low Energy) to read mobile credentials.\n2. Standard Wiegand readers cannot read phones.\n3. Verify the reader model (e.g., HID Signo).\n4. Ensure the user's phone has NFC/Bluetooth enabled, and the mobile credential was properly provisioned in the HID Mobile Access portal and assigned to the user's Apple ID.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-240", title: "Access control software database (SQL Express) is full, preventing new users or logs from being saved.", content: "1. SQL Express has a 10GB size limit.\n2. Open SQL Server Management Studio (SSMS).\n3. Right-click the database -> Properties -> Files.\n4. Check the size.\n5. To free space, run a shrink operation (Tasks -> Shrink -> Database).\n6. Then, in the access software settings, reduce the log retention period (e.g., from 365 days to 90 days) to prevent the database from filling up again.", category: "Access Control", tags: ["access","control","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-241", title: "TeamViewer displays \"Not Ready\" and does not show an ID or Password.", content: "1. The TeamViewer service has crashed or the network adapter is blocked.\n2. Open Services (`services.msc`), find \"TeamViewer\", and restart it.\n3. If it fails to start, open Command Prompt as Admin and run `netsh winsock reset`, then reboot.\n4. If the issue persists, uninstall TeamViewer, delete the `%appdata%\\TeamViewer` folder, and reinstall the latest version to clear corrupted configurations.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-242", title: "AnyDesk immediately closes the connection with \"Session ended\" or \"Connection blocked\".", content: "1. AnyDesk's automated abuse detection has likely triggered due to rapid connections or a changed IP.\n2. On the remote machine, open AnyDesk -> Settings -> Security.\n3. Ensure \"Enable unattended access\" is checked and the security level is set to \"Allow connections\" if appropriate.\n4. If blocked globally, AnyDesk support must whitelist the ID.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-243", title: "Windows RDP fails with \"An authentication error has occurred. The function requested is not supported\" (Code 0x304).", content: "1. This is a CredSSP (Credential Security Support Provider) encryption oracle remediation issue.\n2. Open Registry Editor (`regedit`) on the CLIENT machine (not the server).\n3. Navigate to `HKLM\\Software\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\CredSSP\\Parameters`.\n4. Create a DWORD named `AllowEncryptionOracle` and set it to `2`.\n5. Reboot the client PC and try connecting again.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-244", title: "Chrome Remote Desktop shows the remote computer as \"Offline\" even though the user confirms it is turned on and online.", content: "1. The Chrome Remote Desktop background service (chromoting) has crashed.\n2. Instruct the user to press `Ctrl + Shift + Esc` to open Task Manager.\n3. Go to \"Details\" tab, look for `remoting_host.exe`, and end the task.\n4. Open Chrome, go to chrome://apps, launch Chrome Remote Desktop, and it will automatically restart the background service, turning the status back to \"Online\".", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-245", title: "Zoho Assist fails to connect from a corporate network, throwing a proxy or connection error.", content: "1. The corporate firewall is deep-packet inspecting and blocking Zoho's proprietary relay traffic.\n2. In the Zoho Assist technician console, go to Session Settings -> Connection Mode.\n3. Change it from \"Direct\" to \"Relay\" or \"HTTPs Proxy\".\n4. If using a proxy, ensure the technician console is configured to use the corporate proxy settings under Tools -> Options -> Proxy.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-246", title: "TeamViewer pops up with \"Commercial Use Suspected\" and limits session time to 5 minutes.", content: "1. TeamViewer's heuristic algorithm detected corporate network characteristics or installed software.\n2. If the company has a corporate license, open TeamViewer -> Help -> Activate License and enter the corporate credentials.\n3. If it's a false positive on a free personal version, submit an appeal to TeamViewer support, or reset the ID by uninstalling, deleting registry keys in `HKLM\\SOFTWARE\\WOW6432Node\\TeamViewer`, and reinstalling.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-247", title: "Connecting via RDP results in a black screen immediately after entering credentials, but the session is active.", content: "1. This is a GPU/display driver rendering issue in the RDP session.\n2. Press `Ctrl + Alt + End` to bring up the secure attention sequence.\n3. Open Task Manager (`File -> Run new task`), type `explorer.exe` and hit Enter.\n4. If that fails, disable UDP transport over RDP on the client PC by running this command in CMD: `reg add \"HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows NT\\Terminal Services\\Client\" /v fClientDisableUDP /t REG_DWORD /d 1 /f`.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-248", title: "File transfer is greyed out in AnyDesk, preventing remote file uploads/downloads.", content: "1. File transfer permissions are denied on the remote side.\n2. Instruct the user to open AnyDesk on their end, click the three-line menu -> Settings -> Permissions.\n3. Under \"Interaction\", ensure \"Allow file transfer\" is set to \"Always\" or \"Ask\".\n4. If using unattended access, the access control profile assigned to your technician ID must explicitly have file transfer enabled.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-249", title: "Remote session performance is extremely laggy, with audio echoing and delayed keystrokes.", content: "1. The remote software is consuming too much bandwidth.\n2. In TeamViewer, reduce the quality to \"Optimize speed\" and disable \"Show remote cursor\".\n3. In AnyDesk, lower the \"Display Quality\" to \"Balanced\" or \"Poor\".\n4. For audio echoing, ensure the remote PC's speakers are muted in the remote session so your microphone doesn't pick up their audio output and send it back.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-250", title: "The user cannot see the \"Accept Prompt\" for Zoho Assist because it is hidden behind a full-screen application.", content: "1. Instruct the user to press `Alt + Tab` to cycle through open windows to find the prompt.\n2. If that fails, have them press `Ctrl + Shift + Esc` to open Task Manager, which will force the prompt to the background, then minimize Task Manager.\n3. For future unattended support, deploy the Zoho Assist unattended agent via the executable so no prompt is required.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-251", title: "Mac to PC RDP connection fails with a certificate warning every single time it connects.", content: "1. The Windows PC is using a self-signed RDP certificate that the Mac doesn't trust.\n2. Open the Microsoft Remote Desktop app on the Mac.\n3. Select the PC connection, click \"Edit\", and scroll down to the \"Redirection\" or \"Security\" section.\n4. Change the security profile from \"If server authentication fails, connect anyway\" to \"Always connect, even if unauthenticated\" to suppress the prompt.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-252", title: "Enabling TeamViewer VPN adapter causes the local internet connection on the host machine to drop.", content: "1. The TeamViewer VPN is overriding the local gateway.\n2. This is highly deprecated; avoid using TeamViewer VPN.\n3. Instead, establish a standard remote screen-sharing session and use tools like OneDrive or a web-based file transfer.\n4. If VPN is strictly required, manually configure the IPv4 properties of the TeamViewer VPN adapter to NOT use the default gateway on the remote network.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-253", title: "Chrome Remote Desktop session drops exactly after 10 minutes of inactivity.", content: "1. A power setting or screensaver is severing the connection.\n2. On the remote PC, go to Settings -> System -> Power & sleep.\n3. Set \"Screen\" and \"Sleep\" to \"Never\" when plugged in.\n4. Additionally, disable any 3rd-party lock screens (like DLP tools or Dell Data Protection) that might force a lockout and terminate the remote rendering session.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-254", title: "User provides an AnyDesk ID, but the technician gets \"Invalid ID or Alias\".", content: "1. The user is likely reading the \"Alias\" (e.g., `John_Desktop`) which can change if the hostname changes, or they are reading the wrong number.\n2. AnyDesk IDs are strictly 9-10 digits.\n3. Have the user look specifically for the number under \"Your ID\".\n4. Ensure there are no spaces copied.\n5. Verify the user actually has AnyDesk installed and isn't looking at a different software's ID.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-255", title: "Cannot hear Windows server notification sounds or application sounds during an RDP session.", content: "1. Audio redirection is disabled in the RDP client.\n2. Before connecting, open the RDP file in Notepad (or click \"Show Options\" in mstsc).\n3. Go to the \"Local Resources\" tab.\n4. Under \"Remote audio\", check the box \"Play on this computer\".\n5. Connect to the server.\n6. Also, ensure the server's server-side sound driver (`Remote Desktop Audio` or `Windows Audio` service) is running.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-256", title: "TeamViewer fails to start screen recording with \"Missing codec\".", content: "1. The Windows N edition (or a stripped-down corporate image) is missing the Windows Media Feature Pack.\n2. Download and install the \"Media Feature Pack\" for the specific Windows version from the Microsoft Update Catalog.\n3. Restart the PC, then try the TeamViewer screen recording function again.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-257", title: "Remote Desktop connection over a site-to-site VPN is extremely slow, taking minutes to draw windows.", content: "1. The VPN MTU is causing packet fragmentation.\n2. On the client PC, open CMD as admin and limit the RDP MTU: `netsh interface ipv4 set subinterface\n3. \"Remote Desktop Connection\" mtu=1200 store=persistent`. Alternatively, edit the `.rdp` file, add the line `session bpp:i:16` to lower the color depth from 32-bit to 16bit, significantly reducing bandwidth usage.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-258", title: "Zoho Assist unattended agent deployment fails with \"Error 1603: Fatal error during installation\".", content: "1. A previous corrupted installation is blocking the MSI.\n2. Download the Microsoft Program Install and Uninstall Troubleshooter.\n3. Run it and select \"Uninstalling\" to forcefully remove the old Zoho Agent.\n4. If that fails, use `msiexec /x {Zoho-GUID} /qb` from the command line using the GUID found in the registry under `HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall`.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-259", title: "Copy/paste (clipboard) does not work between the local PC and the remote RDP session.", content: "1. The `rdpclip.exe` process has crashed on the remote machine.\n2. In the remote session, open Task Manager.\n3. Go to \"Details\" tab, find `rdpclip.exe`, and end the task.\n4. Then, go to \"File\" -> \"Run new task\", type `rdpclip.exe`, and press Enter.\n5. Clipboard functionality will be instantly restored.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-260", title: "User accidentally closed the AnyDesk accept window and doesn't know how to get it back.", content: "1. On the remote user's PC, look at the system tray (bottom right corner, near the clock).\n2. If the AnyDesk icon is there, double-click it to bring the accept/deny prompt back to the foreground.\n3. If it is not in the tray, they will need to open AnyDesk from the Start Menu.\n4. To prevent this in the future, check \"Always show this dialog\" in the AnyDesk security settings.", category: "Remote Assistance", tags: ["remote","assistance","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-261", title: "User is locked out of Active Directory, and Windows says \"The referenced account is currently locked out.\"", content: "1. Open Active Directory Users and Computers (ADUC).\n2. Find the user, right-click -> Properties -> Account tab.\n3. Uncheck \"Account is locked out\".\n4. To find the source of the lockout, download and run the Microsoft Account Lockout and Management Tools (`ALTools.exe`), specifically `LockoutStatus.exe`, to see which domain controller holds the lock and which machine caused it (usually an old phone with a cached password or a mapped drive).", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-262", title: "User gets \"Your account has been disabled. Please see your system administrator\" at Windows login.", content: "1. The AD account object has been disabled.\n2. Open ADUC, locate the user.\n3. Their icon will have a downward-pointing arrow.\n4. Right-click -> Enable Account.\n5. Verify with HR or the manager that this was not an intentional offboarding.\n6. If it was a mistake, check your Identity Governance (IGA) tools or HR feed scripts to see why it triggered a disable action.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-263", title: "User receives \"AADSTS50020: User account not in directory\" when trying to log into Microsoft 365.", content: "1. The user is typing their email address incorrectly (e.g., `john@companny.com` instead of `john@company.com`), or they are a guest in another tenant and are trying to log into the wrong tenant URL.\n2. Verify the exact User Principal Name (UPN) in Azure AD.\n3. If the UPN is correct, clear the browser cache/cookies, as a stale cached token might be pointing to an old, deleted directory.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-264", title: "Self-Service Password Reset (SSPR) fails with \"We couldn't verify your identity\" in Azure AD.", content: "1. The user's authentication methods are out of date.\n2. As an admin, log into the Entra ID portal -> Users -> Authentication methods.\n3. Check the user's registered methods.\n4. If their phone number changed, click \"Require re-register MFA\" to force them to set up new methods on their next login.\n5. Ensure the SSPR policy allows the methods they are trying to use (e.g., mobile app code vs. email OTP).", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-265", title: "MFA prompt is not appearing on the user's Microsoft Authenticator app during login.", content: "1. The push notification is being blocked by iOS/Android battery optimization, or the app is out of sync.\n2. Have the user open the Authenticator app manually.\n3. If the prompt isn't there, click \"I can't sign in\" on the login screen and choose \"Use a different verification option\" to select a code instead.\n4. To fix the app, go to app settings -> App Settings -> \"Restore backup\" or \"Resync account\" to re-establish the notification channel.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-266", title: "Okta SSO login results in an infinite loop between the company portal and the Okta login page.", content: "1. This is a SAML assertion failure or cookie conflict.\n2. First, clear the browser cookies for the SaaS app and `okta.com`.\n3. If it persists, the issue is likely a clock skew.\n4. Okta requires system time to be within 2 minutes of UTC.\n5. Check the NTP sync on the Okta Agent/Server.\n6. Also, verify the SAML Certificate in Okta hasn't expired or been rotated without updating the Service Provider (SP) metadata.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-267", title: "Google Workspace user says \"Invalid Password\" after the admin explicitly reset it.", content: "1. The user is likely logged into another Google account in the browser, and the browser is autofilling the wrong credentials.\n2. Have the user open an Incognito/Private window and try logging in with the new password.\n3. If it works, they need to clear their saved passwords in Chrome for `accounts.google.com`.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-268", title: "User was added to an Active Directory Security Group, but still gets \"Access Denied\" to the network share.", content: "1. The user's Kerberos ticket does not contain the new group yet (default AD replication is 15 minutes, but the ticket lasts longer).\n2. The user must log off and log back on, OR open CMD and run `klist purge` to clear the ticket, then access the share to generate a new ticket with the updated group memberships.\n3. Do not reboot the file server.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-269", title: "Azure AD Connect sync fails, and a newly created on-prem AD user is missing from Exchange Online.", content: "1. Force a Delta Sync.\n2. On the Azure AD Connect server, open PowerShell as Admin.\n3. Run `Import-Module ADSync`.\n4. Then run `Start-ADSyncSyncCycle -PolicyType Delta`.\n5. Wait 2-3 minutes.\n6. Check the Exchange Admin Center to see if the user now appears.\n7. If they don't, check the ADSync connector space for synchronization errors (e.g., ambiguous UPN conflict).", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-270", title: "User gets \"You do not have access to this application\" when clicking a SaaS app tile in Okta.", content: "1. The user is not assigned to the application in Okta.\n2. Log into Okta Admin Dashboard -> Applications -> [App Name] -> Assignments tab.\n3. Click \"Assign\" -> \"Assign to People\".\n4. Search for the user and assign them the correct application profile/group.\n5. The tile will appear on their Okta dashboard within 60 seconds.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-271", title: "Users are not receiving the \"Password Expiration\" warning prompt, leading to sudden account lockouts.", content: "1. If users work remotely and connect via VPN, the warning prompt might not trigger until they are on the LAN.\n2. Check the Domain Group Policy: `Computer Configuration -> Windows Settings -> Security Settings -> Local Policies -> Security Options -> \"Interactive logon: Prompt user to change password before expiration\"`.\n3. Ensure it is set to a reasonable number of days (e.g., 5-14).", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-272", title: "A user's last name changed (marriage), and now their UPN and Email were changed, breaking their logins.", content: "1. Changing a UPN in AD breaks the link to the existing Exchange mailbox and Azure AD object.\n2. The proper procedure is to add the NEW email as an alias (SMTP), keep the old UPN as the primary login, and set the new email as the \"Reply-To\" address.\n3. If already changed, you must use `Set-Mailbox -WindowsEmailAddress` in Exchange PowerShell and run a hard sync in Azure AD Connect to repair the GUID mapping.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-273", title: "A Help Desk admin cannot reset a user's password in Google Workspace; the option is greyed out.", content: "1. The Help Desk admin's custom role does not have the \"Reset Password\" privilege.\n2. A Super Admin must go to Admin Console -> Account -> Admin roles -> [Help Desk Role] -> Privileges.\n3. Expand \"Users\" and check the box for \"Reset passwords\".\n4. Save the role.\n5. The Help Desk admin will now have immediate access to the password reset button.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-274", title: "User receives \"Sorry, we can't sign you in\" with a Correlation ID when logging into Microsoft 365.", content: "1. Copy the Correlation ID and go to `https://login.microsoftonline.com/error`.\n2. Paste the ID to decode the exact error.\n3. 90% of the time, this is a Conditional Access Policy block.\n4. For example, the policy requires MFA, but the user has none registered; or the policy blocks access from the user's current country/IP.\n5. Adjust the Conditional Access policy in Entra ID accordingly.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-275", title: "Okta reports \"Factor Locked\" for a user trying to log in.", content: "1. The user failed MFA too many times, triggering Okta's brute-force protection.\n2. Log into Okta Admin -> Directory -> People -> [User] -> Factor Enrollments.\n3. Find the locked factor (e.g., Okta Verify) and click the \"Unlock\" icon.\n4. Instruct the user to wait 5 minutes before attempting to log in again to allow the lockout timer to clear fully.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-276", title: "Windows 11 domain-joined laptop throws \"The trust relationship between this workstation and the primary domain failed\".", content: "1. The local machine's secure channel password is out of sync with AD (often caused by restoring a VM from an old snapshot or being off-network for >30 days).\n2. Log in with a local administrator account (not cached domain creds).\n3. Open PowerShell as Admin.\n4. Run `Test-ComputerSecureChannel -Repair -Credential (Get-Credential)`.\n5. Enter domain admin credentials.\n6. Reboot.\n7. If that fails, remove from domain via `System Properties`, reboot, and rejoin.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-277", title: "User cannot log into a Shared Mailbox in Outlook, getting \"Access Denied\" despite having a license.", content: "1. Shared mailboxes do NOT require and should NOT have user licenses.\n2. The issue is permissions.\n3. In the M365 Admin Center -> Users -> Active Users -> Click the user -> Mail -> Mailbox permissions.\n4. Under \"Read and manage permissions\", add the Shared Mailbox email address.\n5. Wait 15 minutes, then add the Shared Mailbox via Auto-Mapping in Outlook.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-278", title: "User is a local admin on their PC but gets \"Windows protected your PC\" / UAC prompts when trying to install software.", content: "1. UAC is functioning as designed, but if it's blocking standard admin tasks, the UAC level might be set to \"Always Notify\".\n2. To change it, open `UserAccountControlSettings.exe` from the Run dialog.\n3. Lower the slider to \"Notify me only when apps try to make changes to my computer\".\n4. Note: If this is a compliant environment, do not disable UAC entirely; use an enterprise elevation tool like CyberArk or BeyondTrust instead.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-279", title: "An external B2B guest user in Azure AD cannot access the shared Teams channel or SharePoint site.", content: "1. The guest account setup is incomplete.\n2. Ensure the user received the invitation email and clicked \"Accept\".\n3. In Entra ID -> Users -> Guest users, check their \"Source\" and \"Redemption Status\".\n4. It must say \"Accepted\".\n5. Then, go to Teams -> manage the team -> Add member, and add the guest's email.\n6. They must be explicitly added to the M365 Group, not just invited to the tenant.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-280", title: "An Active Directory user was accidentally deleted and needs to be recovered immediately.", content: "1. Open ADUC.\n2. Click \"View\" -> \"Enable Advanced Features\".\n3. Navigate to the \"Deleted Objects\" container (you may need to enable \"View\" -> \"Filter Options\" -> check \"Deleted Objects\").\n4. Find the user, right-click, and select \"Restore\".\n5. If the object has passed the tombstone lifetime (usually 180 days), you cannot restore it natively; you must use a 3rd-party AD recovery tool or restore from a System State backup.", category: "User Account Management", tags: ["user","account","management","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-281", title: "iPhone is stuck in a continuous reboot loop, displaying the Apple logo and then turning off.", content: "1. Force restart the device first (Quickly press Vol Up, Vol Down, then hold Power until the Apple logo appears).\n2. If it loops again, connect to a PC/Mac, open Finder/iTunes, and perform a Recovery Mode restore.\n3. If Recovery Mode fails to load, perform a DFU (Device Firmware Update) restore to bypass the bootloader entirely and flash the OS.\n4. If DFU fails, the NAND flash storage has hardware-level degradation.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-282", title: "Face ID fails to recognize the user's face repeatedly, or the \"Face ID Not Available\" message appears.", content: "1. Ensure the TrueDepth camera is not blocked by a case or screen protector.\n2. Go to Settings -> Face ID & Passcode.\n3. If \"Set Up an Alternate Appearance\" is available, use it to add a second scan (helps with glasses/masks).\n4. If completely unavailable, the flex cable connecting the screen to the motherboard may have been severed (common after a third-party screen replacement), or the IR dot projector has failed, requiring Apple hardware repair.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-283", title: "iPhone charges extremely slowly or only charges when the cable is held at a specific angle.", content: "1. Do NOT use metal objects to clean the port.\n2. Use a wooden toothpick or a non-conductive nylon brush to gently scrape out compacted pocket lint from the Lightning/USB-C port.\n3. If the port is clean and it still wiggles, the charging pins inside the port are bent or the port has desoldered from the motherboard.\n4. The entire charging assembly (flex cable) must be replaced.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-284", title: "iOS software update fails with \"Unable to Verify Update\" or gets stuck at \"Estimating time remaining...\".", content: "1. The device lacks temporary storage to unpack the OTA file, or Apple's servers are blocking it.\n2. Go to Settings -> General -> iPhone Storage.\n3. Find the iOS update file and tap \"Delete Update\".\n4. Connect the iPhone to a PC/Mac and update via Finder/iTunes, which streams the update without needing gigabytes of local free space.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-285", title: "iPhone screen registers \"ghost touches\" (opens apps, types randomly) when not being touched.", content: "1. Remove the phone case and screen protector; trapped moisture or pressure often causes capacitive ghost touches.\n2. If the issue persists, disconnect from power (cheap chargers cause electrical interference on the digitizer).\n3. If still occurring, the display digitizer layer has suffered physical micro-fractures or electrical shorting and must be replaced.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-286", title: "iMessage and FaceTime activate with an error, or the user's phone number is missing from the \"Send & Receive\" list.", content: "1. Turn off iMessage and FaceTime, wait 60 seconds, and turn them back on.\n2. Go to Settings -> Messages -> Send & Receive.\n3. If the phone number is greyed out, go to Settings -> Phone -> My Number and ensure it is correct.\n4. If still failing, the iOS Keychain is desynced.\n5. Sign out of the Apple ID entirely, reboot, and sign back in to re-provision the iMessage push certificates.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-287", title: "iPhone shows \"Storage Almost Full\" but the user has barely any photos or apps installed.", content: "1. The \"System Data\" or \"Other\" cache is bloated.\n2. Go to Settings -> General -> iPhone Storage.\n3. Offload large apps (keeps documents, deletes the app core).\n4. Check Settings -> Safari -> Clear History and Website Data.\n5. If System Data is over 10GB, a backup/restore is required: Back up to Mac/PC, erase the iPhone, and restore from the backup to clear the corrupted system snapshot.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-288", title: "iPhone camera app shows a black screen, but the front-facing \"selfie\" camera works fine.", content: "1. Open the camera and swipe between 0.5x, 1x, and 2x/3x zoom.\n2. If one of the lenses is black but the others work, that specific physical lens module or optical image stabilizer (OIS) has failed.\n3. Try lightly tapping the camera lens with your finger (can unstick a frozen OIS).\n4. If it remains black, the rear camera module requires hardware replacement.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-289", title: "Corporate iPhone does not appear in Finder/iTunes when plugged into the PC, but it charges.", content: "1. The Apple Mobile Device USB Driver has crashed or is missing.\n2. On Windows, open Device Manager -> Universal Serial Bus controllers -> \"Apple Mobile Device USB Driver\".\n3. Right-click -> Update Driver.\n4. If missing, unplug the phone, open Services (`services.msc`), stop \"Apple Mobile Device Service\", delete the `C:\\Program Files\\Common Files\\Apple\\Mobile Device Support` folder, reinstall iTunes, and restart the service.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-290", title: "User reports battery health dropping rapidly (e.g., from 95% to 85% in a month).", content: "1. Check Settings -> Battery -> Battery Health & Charging.\n2. If \"Optimized Battery Charging\" is off, turn it on.\n3. Check for apps using significant background activity.\n4. If the user frequently uses fast-charging or wireless charging while the phone is hot (e.g., GPS navigation), this accelerates chemical degradation.\n5. If the phone is less than a year old, Apple typically replaces batteries that drop below 80% under warranty.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-291", title: "During phone calls, the other person cannot hear the user, but speakerphone and headphones work.", content: "1. The primary bottom microphone (or noise-canceling mesh) is blocked.\n2. Brush out the microphone holes at the bottom of the phone next to the charging port.\n3. If clear, open Voice Memos and record; if it's silent, the mic is dead.\n4. If Voice Memos works, go to Settings -> Accessibility -> Audio/Visual and turn OFF \"Phone Noise Cancellation\" (this feature uses a secondary mic that often fails, muting the primary one).", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-292", title: "Third-party apps (Outlook, Teams, Slack) crash immediately upon opening after an iOS update.", content: "1. The app's local cache is incompatible with the new iOS API.\n2. Do not just delete the app (you lose local offline data).\n3. Instead, offload the app: Settings -> General -> iPhone Storage -> [App Name] -> Offload App.\n4. This deletes the core code but keeps the documents/data.\n5. Re-download the app from the App Store to pull the updated version.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-293", title: "iPhone disconnects from corporate Wi-Fi every few minutes and requires manual re-authentication.", content: "1. The Wi-Fi profile's \"Auto-Join\" is disabled, or the MDM (Jamf/Intune) pushed a certificate that has expired.\n2. Go to Settings -> Wi-Fi -> Tap the \"i\" next to the network.\n3. Ensure \"Auto-Join\" is ON.\n4. If using 802.1x (EAP-TLS), check if the device's certificate is valid via the MDM console.\n5. As a workaround, forget the network and re-install the Wi-Fi profile from the MDM Company Portal app.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-294", title: "iPhone screen is completely unresponsive to touch, but notifications still pop up and the phone rings.", content: "1. Force restart the device.\n2. If touch returns, it was a software freeze in the iOS touch subsystem.\n3. If touch remains dead after a reboot, the digitizer cable has failed or come loose inside.\n4. If the screen was recently replaced by a third party, the aftermarket display lacks the original IC chips required by iOS, causing a permanent \"Touch Disease\" failure.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-295", title: "iCloud Backup fails overnight with \"Not Enough iCloud Storage\", even though the user bought a 50GB plan.", content: "1. The user is likely signed into a different Apple ID for iCloud than the one that bought the storage, or \"iCloud Drive\" apps are syncing massive offline files.\n2. Go to Settings -> [User Name] -> iCloud -> Manage Account Storage.\n3. Check which Apple ID is listed at the top.\n4. Scroll down to see exactly what is consuming the storage (often WhatsApp backups or third-party app data like Google Drive caches).", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-296", title: "AirPods or another Bluetooth accessory connects but audio keeps cutting out or only plays from one earbud.", content: "1. Go to Settings > Bluetooth, tap the \"i\" next to the device, and select \"Forget This Device\".\n2. Place the AirPods back in the case, close the lid for 30 seconds, then reopen it and hold the setup button on the back of the case until the light flashes white.\n3. Re-pair from Settings > Bluetooth.\n4. If only one earbud drops audio, clean the earbud contacts and the charging case contacts with a dry, soft brush, as a poor charge often causes one side to run low and disconnect first.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-297", title: "\"Hey Siri\" or the Siri button stops responding, even though Siri is enabled in Settings.", content: "1. Go to Settings > Siri & Search and toggle \"Listen for Hey Siri\" off, then back on to re-train the trigger phrase.\n2. If using AirPods, ensure \"Press and Hold AirPods\" or \"Hey Siri\" is still assigned to the stem/button under Settings > Bluetooth > [AirPods] > i.\n3. If Siri still doesn't respond, check Settings > Screen Time > Content & Privacy Restrictions to confirm Siri hasn't been restricted, and toggle Airplane Mode on/off to reset the network connection Siri relies on for requests.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-298", title: "Apple Pay or a specific card in Wallet fails with \"Cannot Add Card\" or does not trigger at checkout terminals.", content: "1. Confirm the card issuer's app/network isn't reporting an outage.\n2. Remove the card from Settings > Wallet & Apple Pay, then re-add it, completing the SMS/email verification step from the bank.\n3. If the phone simply won't trigger the terminal at all, the NFC antenna (a small coil near the top of the phone, behind the camera) is failing; this is common after a drop or an aftermarket back-glass repair, and requires the NFC/charging flex assembly to be replaced.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-299", title: "iPhone shows full signal bars but calls and texts fail to send, with no error message.", content: "1. Toggle Airplane Mode on for 15 seconds and back off to force a fresh connection to the cell tower.\n2. Go to Settings > General > About and check if a \"Carrier Settings Update\" prompt appears; install it if so, as carriers frequently push updates that fix silent registration failures.\n3. If the issue persists, remove and reseat the physical SIM (or, on eSIM-only models, go to Settings > Cellular and toggle the eSIM line off and back on) to force the modem to re-register with the network.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-300", title: "A corporate iPhone displays \"Remote Management\" during setup and cannot be activated without contacting an unknown administrator.", content: "1. This means the device is enrolled in Automated Device Enrollment (ADE/DEP) and is supervised by an MDM (Jamf, Intune, etc.), which is expected behavior for company-owned devices and is not a lock to bypass.\n2. Confirm with IT which MDM tenant the device belongs to and have them push the enrollment profile or release the device from the Apple Business Manager portal if it was assigned in error.\n3. Never use third-party \"MDM bypass\" tools on a corporate device, as this violates company policy and can void the device's warranty and security compliance.", category: "iPhone Support (Hardware & Software)", tags: ["iphone","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-301", title: "Android phone is stuck in a \"Bootloop\" at the manufacturer logo (e.g., Samsung Galaxy or Google Pixel).", content: "1. Boot into Android Recovery Mode (Hold Power + Volume Up).\n2. Select \"Wipe Cache Partition\" (does not delete user data).\n3. Reboot.\n4. If it loops again, boot to Recovery and select \"Wipe Data/Factory Reset\" (erases the phone).\n5. If it STILL loops after a factory reset, the eMMC/UFS storage chip has suffered hardware failure (common on older Samsungs) or the motherboard is shorting.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-302", title: "A vertical pink or green line has appeared on the screen and won't go away.", content: "1. This is a physical hardware defect in the OLED panel matrix (caused by microscopic flexing of the motherboard/frame).\n2. There is absolutely no software fix.\n3. Taking a screenshot will not capture the line (proving it's hardware).\n4. The OLED display panel must be replaced.\n5. Check if the device is under warranty, as many OEMs are replacing screens for single-line defects for free.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-303", title: "Google Play Store throws \"Error 919\", \"DF-DFERH-01\", or \"App could not be downloaded\" when updating apps.", content: "1. The Play Store cache is corrupted.\n2. Go to Settings -> Apps -> See All Apps -> Google Play Store -> Storage & Cache -> Clear Cache.\n3. Do the exact same for \"Google Play Services\".\n4. If it persists, go to Settings -> Apps -> Google Play Store -> Storage & Cache -> Clear Storage (erases your Play Store login), then log back in.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-304", title: "Android device shows \"Insufficient Storage Available\" when trying to install a 50MB app, despite having 5GB free.", content: "1. The phone's `/data` partition is full of cached OTA update files or app OBB data.\n2. Go to Settings -> Storage -> Tap on \"Cached data\" and confirm deletion.\n3. If that fails, use a PC to delete the `.ota` file in the `/Android/data/com.android.updater/` folder via USB, or use the \"Storage Analyzer\" built into Samsung/OneUI to find hidden large files.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-305", title: "Phone charges extremely slowly, and a notification says \"Moisture detected in USB-C port\" even though the phone is dry.", content: "1. The moisture sensor pins inside the USB-C port are stuck or corroded.\n2. Do NOT blow compressed air into it (pushs water deeper).\n3. Gently insert a dry cotton swab or a wooden toothpick to absorb the moisture.\n4. Leave the phone upright in a dry, warm area for 4 hours.\n5. If the warning persists, the pins are permanently corroded, and the USB-C daughterboard must be replaced.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-306", title: "All apps using web views (Gmail, Teams, banking apps) crash instantly with a white screen or \"WebView\" error.", content: "1. The \"Android System WebView\" component has a bug or is disabled.\n2. Open the Play Store, search for \"Android System WebView\", and update it.\n3. If that fails, go to Settings -> Apps -> Android System WebView -> Uninstall Updates (reverts to factory version).\n4. Then restart the phone and update it again from the Play Store.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-307", title: "Phone is stuck in \"Safe Mode\" (watermark in bottom left corner) and won't exit despite rebooting.", content: "1. Safe Mode is triggered by holding the Volume Down button during boot, OR a faulty physical button is stuck.\n2. Inspect the Volume Down button; press it rapidly to see if it \"pops\" back up.\n3. If it's physically stuck, debris is underneath it.\n4. If the button is fine, boot to Recovery Mode, do a \"Wipe Cache Partition\", and reboot.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-308", title: "Ex-employee returned a company Android phone, and it is locked with \"This device is protected by Factory Reset Protection (FRP)\".", content: "1. Do not attempt to bypass FRP via shady third-party tools.\n2. Check if the device is enrolled in an MDM (Intune/AirWatch).\n3. Log into the MDM console and issue a \"Factory Reset\" command; the MDM cryptographically bypasses FRP.\n4. If the device was never enrolled in MDM, you must contact the ex-employee to get their Google account password, or provide Google Support with the original purchase receipt to unlock the device.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-309", title: "During a phone call, the screen stays black when the user pulls the phone away from their face.", content: "1. The proximity sensor is failing or blocked.\n2. Remove the screen protector and clean the top speaker grill.\n3. On Samsung devices, dial `*#0*#` to enter Service Mode.\n4. Tap \"Sensor\" and hover your hand over the top of the screen.\n5. If the graph doesn't spike, the sensor is dead.\n6. If it does spike, the software is ignoring it; disable \"Skip screen timeout during calls\" in Phone app settings.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-310", title: "Android Auto connects to the car, but there is no audio for navigation or music, only phone calls work.", content: "1. The car's infotainment system selected the wrong audio source.\n2. On the car screen, go to Audio Settings and change the media source from \"Bluetooth\" to \"Android Auto\".\n3. On the phone, go to Settings -> Apps -> Android Auto -> Storage -> Clear Cache.\n4. Also, ensure the USB cable supports data (some cheap gas-station cables are charge-only and fail to transmit media protocols).", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-311", title: "The back glass of the phone is cracking, or the screen is lifting at the edges, and the battery is draining in 2 hours.", content: "1. SAFETY HAZARD.\n2. The lithium-ion battery is swelling (off-gassing) due to internal shorting or end-of-life degradation, physically pushing the screen/frame apart.\n3. STOP USING THE PHONE IMMEDIATELY.\n4. Do not charge it.\n5. The battery is at risk of thermal runaway (fire).\n6. It must be taken to a professional repair shop to safely puncture and discharge the swollen battery before replacing it.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-312", title: "The \"System UI\" or \"System\" process crashes repeatedly, causing the home screen to flash and reload.", content: "1. A third-party widget or a rogue launcher is crashing the UI.\n2. Boot into Safe Mode.\n3. If the crashing stops in Safe Mode, uninstall recently added widgets (weather, clock) or change the default Home Screen app.\n4. If it crashes in Safe Mode, go to Settings -> System -> Developer Options -> disable \"Demo mode\" or clear the data for the \"System UI\" app via ADB (`adb shell pm clear com.android.systemui`).", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-313", title: "Phone gets incredibly hot (over 105°F/40°C) and the battery drains from 100% to 20% in an hour while idle.", content: "1. A rogue app is keeping the CPU awake.\n2. Go to Settings -> Battery -> Battery Usage.\n3. Look for an app using an abnormally high percentage of background usage.\n4. Force stop it.\n5. If \"Android System\" is the culprit, check for a stuck OTA update downloading in the background.\n6. Also, if the phone is in an area with a weak 5G signal, disable 5G in Settings -> Mobile Network (the radio will ping-pong violently, generating massive heat).", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-314", title: "Push notifications for Outlook, WhatsApp, or Teams arrive late, only showing up when the user opens the app.", content: "1. Android's Doze mode is aggressively killing the app's background connection.\n2. Go to Settings -> Apps -> [App Name] -> Battery -> Select \"Unrestricted\".\n3. Ensure \"Adaptive Battery\" or \"Put unused apps to sleep\" is disabled for critical business apps.\n4. For Samsung devices, ensure the app is NOT in the \"Deep Sleeping Apps\" list in Battery Care settings.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-315", title: "Corporate Android device fails to enroll in Microsoft Intune/Company Portal with \"Error 0x87D1041C\" or \"Device not compliant\".", content: "1. Ensure the device's Date and Time are set to \"Automatic\" (certificate validation fails if time is off).\n2. Go to Settings -> Security -> Encryption & Credentials -> Clear Credentials (removes old, conflicting VPN/Workspace certs).\n3. Uninstall the Company Portal, restart the phone, reinstall it from the Play Store, and retry enrollment.\n4. Ensure no personal VPNs are running during enrollment.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-316", title: "Android phone connects to the car's Bluetooth but disconnects again within a few seconds, repeating the cycle.", content: "1. This is usually a paired-device cache conflict.\n2. On the phone, go to Settings > Connected devices > [Car Name] > tap the gear icon > Forget.\n3. On the car's infotainment system, delete the paired phone entry as well.\n4. Restart the phone, then re-pair from scratch.\n5. If it still loops, go to Settings > Apps > See all apps > Show system apps > Bluetooth (or Bluetooth MIDI Service), and clear its cache and storage before re-pairing.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-317", title: "Samsung device shows \"Warranty Void\" or a Knox security warning after installing a custom app or rooting tool, and MDM enrollment now fails.", content: "1. Samsung Knox permanently trips an e-fuse the moment the bootloader is unlocked or a root exploit is applied; this cannot be reversed by any software update or factory reset.\n2. Once tripped, Knox-dependent features (Secure Folder, Samsung Pay, and most MDM containers) are permanently disabled on that specific device.\n3. The only fix is replacing the device, as Knox counters are hardware-level and non-resettable even by Samsung service centers in most regions.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-318", title: "NFC payments (Google Wallet/Google Pay) fail to trigger at contactless terminals despite NFC being enabled in Settings.", content: "1. Go to Settings > Connected devices > Connection preferences > NFC and confirm it is toggled on, then check \"Contactless payments\" is set to Google Wallet as the default app.\n2. Remove the phone case if it contains a metal plate, magnetic mount, or credit-card holder, as these commonly block the NFC antenna located near the top-back of the device.\n3. If it still fails to trigger, dial the manufacturer's diagnostic code (varies by OEM) to run an NFC hardware self-test; a failed test indicates the NFC coil itself needs replacement.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-319", title: "After a system update, the phone displays \"No SIM Card\" or \"Emergency Calls Only\" even though the SIM was working fine before.", content: "1. Power off the device, remove the SIM tray, and inspect it for a bent tray pin or misseated SIM, then reseat it firmly.\n2. Go to Settings > About phone and check for a pending \"Modem\" or baseband firmware update, as the OS update can desync from the modem firmware.\n3. If reseating doesn't help, go to Settings > System > Reset options > Reset network settings, which clears cached APN and carrier profiles that can become corrupted during major OS updates.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
  { id: "imp-320", title: "Intune Company Portal fails to create a Work Profile, showing \"Couldn't set up work profile\" or getting stuck at \"Setting up your work profile...\".", content: "1. This is usually caused by insufficient storage or a conflicting existing work profile from a previous MDM enrollment.\n2. Go to Settings > Accounts and check for a leftover \"Work profile\" entry; remove it manually if the device was previously enrolled elsewhere.\n3. Ensure at least 1.5GB of free storage is available, since Android Enterprise silently fails the provisioning step if storage runs low.\n4. Reboot, reinstall the Company Portal app from the Play Store, and retry enrollment while connected to WiFi rather than cellular data.", category: "Android Support (Hardware & Software)", tags: ["android","support","hardware","software","troubleshooting","how-to"], isPublished: true, helpfulCount: 0, createdBy: '3', createdAt: day(-10) },
];
